insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('holiday-travel-day-delay-plan-sheet', 'Holiday Travel Day Delay Plan Sheet', 'worksheet'::resource_kind, 'A one-page plan for the travel day that goes wrong: the delayed flight, the full highway, the missed connection, and what to do in the gap.', 'Use it to help a client rehearse a stressful travel day so a delay becomes a known scenario with a short list rather than a collapse.', array['Adults']::text[], '20 minutes, a week before the trip', 'Holiday travel compresses every stressor into one day: crowds, time pressure, family waiting at the other end. The sheet asks the client to name the three most likely delays, the first practical step for each, who gets the first text, what is in the bag for a three-hour wait, and the sentence they say to themselves when the departure board changes. Fill it in while the trip is still abstract. Watch for a client whose plan is all contingency and no comfort; add the snack, the podcast and the walk around the terminal.', '[{"id": "f0", "type": "textarea", "label": "The three delays most likely on my travel day, and the first practical step for each:"}, {"id": "f1", "type": "textarea", "label": "Who gets the first text when plans change, and what it says:"}, {"id": "f2", "type": "textarea", "label": "What is in my bag for a three-hour wait that is not my phone:"}, {"id": "f3", "type": "textarea", "label": "The sentence I say to myself when the departure board changes:"}, {"id": "f4", "type": "textarea", "label": "How the people waiting for me will know I am fine even if I am late:"}, {"id": "f5", "type": "textarea", "label": "After the trip: what actually happened, and what from this sheet I used:"}]'::jsonb, array['stress', 'planning', 'travel']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('password-and-account-chaos-cleanup-pacing-sheet', 'Password and Account Chaos Cleanup Pacing Sheet', 'worksheet'::resource_kind, 'A paced plan for the pile of locked accounts, forgotten passwords and expired cards that a client has stopped opening.', 'Use it to turn an avoided administrative mess into fifteen-minute sittings with a clear stopping point each time.', array['Adults']::text[], '15 minutes a day for two weeks', 'Account chaos is a common avoided task that grows by itself: each locked login makes the next one feel heavier. The sheet lists the accounts that matter most (bank, phone, email, benefits), one sitting per account, a fifteen-minute timer, and a stopping ritual so the client does not slide from one reset into an hour of dread. Watch for a client who wants to do it all at once on a good day and then avoids it for a month; the pacing is the point, and the first account should be the easiest, not the scariest.', '[{"id": "f0", "type": "textarea", "label": "The accounts I have stopped opening, in order of how much they matter:"}, {"id": "f1", "type": "textarea", "label": "The easiest one, and the fifteen-minute sitting I will give it this week:"}, {"id": "f2", "type": "textarea", "label": "Where I will keep the new passwords so this does not happen again:"}, {"id": "f3", "type": "textarea", "label": "My stopping ritual when the timer ends, even if I am mid-task:"}, {"id": "f4", "type": "textarea", "label": "What I tell myself when a reset turns into a phone call and a wait:"}, {"id": "f5", "type": "textarea", "label": "Two weeks in: what is unlocked, and what is still waiting:"}]'::jsonb, array['avoidance', 'planning', 'pacing']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('car-repair-estimate-decision-sheet', 'Car Repair Estimate Decision Sheet', 'worksheet'::resource_kind, 'A sheet for the afternoon the mechanic calls with a number, separating the decision from the panic about money and being taken advantage of.', 'Use it to help a client decide on a repair with the facts in front of them instead of saying yes to everything or driving off on a bad tire.', array['Adults']::text[], '20 minutes when the estimate arrives', 'A repair estimate hits two sore spots at once: money the client did not plan to spend and the fear of being cheated because they do not know cars. The sheet separates what the shop says must be done now, what can wait, the question the client is allowed to ask (can you show me, can I have that in writing), who they can call for a second opinion, and the number above which they will say they need an hour to think. Watch for a client who agrees on the phone to end the discomfort, then stews for a week; the hour to think is the skill.', '[{"id": "f0", "type": "textarea", "label": "What the shop says must be done now, and what they say can wait:"}, {"id": "f1", "type": "textarea", "label": "The questions I am allowed to ask before I say yes:"}, {"id": "f2", "type": "textarea", "label": "Who I can call for a quick second opinion, and what I will ask them:"}, {"id": "f3", "type": "textarea", "label": "The number above which I will say I need an hour to think:"}, {"id": "f4", "type": "textarea", "label": "What I am afraid the mechanic thinks of me, and whether that changes the decision:"}, {"id": "f5", "type": "textarea", "label": "The decision I made, and how I feel about it a day later:"}]'::jsonb, array['decisions', 'stress', 'money']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('first-week-at-a-new-job-anchors-sheet', 'First Week at a New Job Anchors Sheet', 'worksheet'::resource_kind, 'A planner for the first five workdays somewhere new: the few things to learn each day, the one person to talk to, and the evening wind-down.', 'Use it to give a client starting a job a small daily target so the first week is a set of anchors rather than a blur of trying to impress.', array['Adults']::text[], '15 minutes, the weekend before the start date', 'The first week at a new job is a sustained performance for most clients, and the ones who struggle most try to learn everything by Wednesday. The sheet gives each day one thing to learn (where things are, who does what, how lunch works), one person to have a two-minute conversation with, one question it is fine to ask, and an evening that ends the workday on purpose. Watch for a client who fills every box with proving themselves; the anchors are about orientation, not performance, and the question box is there to make asking normal from day one.', '[{"id": "f0", "type": "textarea", "label": "Monday: the one thing to learn, the one person to talk to, and the one question it is fine to ask:"}, {"id": "f1", "type": "textarea", "label": "Tuesday through Thursday: the same three, one line per day:"}, {"id": "f2", "type": "textarea", "label": "Friday: what I want to be able to say I know by the end of the week:"}, {"id": "f3", "type": "textarea", "label": "How each workday ends on purpose: the walk, the change of clothes, the phone put down:"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself when I get something wrong this week:"}, {"id": "f5", "type": "textarea", "label": "End of week one: what I know now that I did not know Monday:"}]'::jsonb, array['planning', 'work', 'routines']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('year-end-review-self-report-draft-sheet', 'Year-End Review Self-Report Draft Sheet', 'worksheet'::resource_kind, 'A drafting sheet for the self-evaluation a client must write at work, turning a blank form into facts, examples and one honest growth area.', 'Use it to help a client who freezes at self-assessment write a fair account of their year instead of an apology or a boast.', array['Adults']::text[], '45 minutes, in two sittings', 'The year-end self-report asks clients to do the thing many of them cannot: describe their own work plainly. Some write three lines of apology; some write a page that sounds like someone else. The sheet gathers the facts first (projects finished, problems handled, things learned), then an example for each, then one growth area in the client''s own words with a next step, and finally a read-through for words like just, only and tried. Watch for a client who cannot find a single accomplishment; walk the calendar month by month with them in session.', '[{"id": "f0", "type": "textarea", "label": "Month by month, the things I actually did this year, before any judgment about them:"}, {"id": "f1", "type": "textarea", "label": "Three accomplishments with a concrete example for each:"}, {"id": "f2", "type": "textarea", "label": "One problem I handled this year that nobody else would have handled the same way:"}, {"id": "f3", "type": "textarea", "label": "A growth area in my own words, and the first step I will take on it:"}, {"id": "f4", "type": "textarea", "label": "Read-through: the words just, only, tried and I guess, and what replaces them:"}, {"id": "f5", "type": "textarea", "label": "How I will feel sending this, and what I will do for the ten minutes afterward:"}]'::jsonb, array['work', 'self-esteem', 'planning']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('boss-replied-with-just-ok-thought-record', 'Boss Replied With Just OK Thought Record', 'cbt'::resource_kind, 'A thought record for the one-word reply from a manager that a client reads as disappointment, with alternative readings and a test.', 'Use it to help a client catch mind reading in a two-letter email and weigh the other explanations before the evening is spent on it.', array['Adults']::text[], '15 minutes', 'A terse reply from someone with power over the client is a reliable trigger for mind reading. The record takes the exact message, the hot thought (they are annoyed, I did it wrong), the feeling and its intensity, then the evidence for and against and at least three other reasons a busy person types OK. The behavioral test is optional but useful: ask one clarifying question the next day and record the answer. Watch for a client who refuses alternatives because the boss really is hard to read; the record is about what the client knows, not what the boss is like.', '[{"id": "f0", "type": "textarea", "label": "The exact message, with the time it arrived and what I was doing:"}, {"id": "f1", "type": "textarea", "label": "My first thought about what it meant, and how strongly I believed it:"}, {"id": "f2", "type": "textarea", "label": "The feeling, and how intense it was out of ten:"}, {"id": "f3", "type": "textarea", "label": "Evidence for my reading, and evidence against it:"}, {"id": "f4", "type": "textarea", "label": "Three other reasons a busy person types OK:"}, {"id": "f5", "type": "textarea", "label": "If I check tomorrow, what I will ask, and what the answer was:"}, {"id": "f6", "type": "textarea", "label": "My belief in the first thought now, out of a hundred:"}]'::jsonb, array['thinking traps', 'work', 'thought record']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('rainy-forecast-ruins-the-weekend-fortune-telling-sheet', 'Rainy Forecast Ruins the Weekend Fortune Telling Sheet', 'cbt'::resource_kind, 'A fortune-telling check for the client who sees rain in the forecast and writes off the weekend before it has started.', 'Use it to help a client notice a prediction, rate it, and plan the weekend they would have if the forecast were just information.', array['Adults', 'Teens']::text[], '15 minutes on Thursday, 10 minutes on Sunday night', 'Forecast fortune telling is small enough to practice on and the pattern is identical to the bigger ones: a single piece of information becomes a verdict about the whole stretch ahead. The sheet records the forecast, the prediction (the weekend is ruined, we will be stuck inside, everyone will be miserable), the mood it produces on Thursday, three things that are still possible in rain, and a Sunday-night check of what the weekend was actually like. Watch for a client who refuses to plan because planning in rain feels pointless; that is the prediction at work.', '[{"id": "f0", "type": "textarea", "label": "The forecast I saw, and when I saw it:"}, {"id": "f1", "type": "textarea", "label": "The prediction I made about the whole weekend, word for word:"}, {"id": "f2", "type": "textarea", "label": "My mood on Thursday after making it, out of ten:"}, {"id": "f3", "type": "textarea", "label": "Three things that are still possible if it rains all day:"}, {"id": "f4", "type": "textarea", "label": "Sunday night: what the weather actually did, and what the weekend was actually like:"}, {"id": "f5", "type": "textarea", "label": "What I will do the next time the forecast turns the week ahead gray:"}]'::jsonb, array['thinking traps', 'predictions', 'behavioral experiment']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('leave-the-party-early-experiment-sheet', 'Leave the Party Early Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment in leaving a gathering when the client wants to, testing the prediction that leaving early is rude or noticed.', 'Use it to help a client who stays past their limit test what actually happens when they say goodnight at the time they chose.', array['Adults', 'Teens']::text[], 'One evening plus a 10 minute debrief', 'Many clients stay at gatherings long after they want to leave because they predict that leaving will offend the host, be remarked on, or confirm that they are no fun. The experiment picks a real event, sets a leaving time in advance, writes the goodbye sentence, and records the prediction with a confidence rating. Afterward the client notes what the host said, whether anyone mentioned it since, and how the evening at home felt. Watch for a client who leaves and then spends the night replaying it; the debrief row for the next day''s evidence catches that.', '[{"id": "f0", "type": "textarea", "label": "The event, and the time I will leave no matter how it is going:"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen when I say goodbye, and how sure I am out of a hundred:"}, {"id": "f2", "type": "textarea", "label": "The goodbye sentence I will use, said out loud once here:"}, {"id": "f3", "type": "textarea", "label": "What the host actually said, and what anyone else did:"}, {"id": "f4", "type": "textarea", "label": "The next day: has anyone mentioned it, and what did the evening at home feel like:"}, {"id": "f5", "type": "textarea", "label": "My confidence in the prediction now, and what I will test next:"}]'::jsonb, array['behavioral experiment', 'predictions', 'boundaries']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('i-feel-guilty-so-i-must-have-done-wrong-sheet', 'I Feel Guilty So I Must Have Done Wrong Sheet', 'cbt'::resource_kind, 'A sheet for untangling emotional reasoning around guilt, asking what the client did, what the guilt says, and whether a jury would agree.', 'Use it to help a client separate the feeling of guilt from the fact of having done something wrong.', array['Adults', 'Teens']::text[], '20 minutes', 'Guilt that arrives without an offense is a form of emotional reasoning: the feeling is treated as proof. The sheet asks the client to state the situation in plain facts, what the guilt claims they did, what a fair-minded friend hearing only the facts would conclude, what rule the guilt is enforcing and whether it is a rule they would hold anyone else to. The last row asks what they would do if the guilt were a false alarm. Watch for a client who reasons their way to innocence and still feels guilty; the sheet is practice at noticing the gap, not erasing the feeling.', '[{"id": "f0", "type": "textarea", "label": "The situation in plain facts, with no adjectives:"}, {"id": "f1", "type": "textarea", "label": "What the guilt says I did wrong:"}, {"id": "f2", "type": "textarea", "label": "What a fair-minded friend who heard only the facts would say:"}, {"id": "f3", "type": "textarea", "label": "The rule the guilt is enforcing, and whether I would hold a friend to the same rule:"}, {"id": "f4", "type": "textarea", "label": "If the guilt is a false alarm, what I would do with the rest of the day:"}, {"id": "f5", "type": "textarea", "label": "If the guilt does fit the facts, the one repair I will make:"}]'::jsonb, array['thinking traps', 'guilt', 'emotional reasoning']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('dropped-call-mid-sentence-thought-record', 'Dropped Call Mid-Sentence Thought Record', 'cbt'::resource_kind, 'A thought record for the call that cuts out at the worst moment, when a client decides the other person hung up on them.', 'Use it to help a client notice how fast a technical glitch becomes a story about rejection and how to check before believing it.', array['Adults', 'Teens']::text[], '10 minutes', 'A dropped call is a tiny event with a reliable sting: the silence is read as a hang-up and the hang-up as a verdict. The record captures the moment, the automatic thought, the body''s reaction, the alternatives (signal, battery, the elevator) and the one action that settles it, which is calling back. Clients who have been hung up on in the past find this one harder, and the sheet makes room for that history without letting it decide the present. Watch for a client who waits for the other person to call back as a test of whether they care.', '[{"id": "f0", "type": "textarea", "label": "What was being said when the call dropped, and who I was talking to:"}, {"id": "f1", "type": "textarea", "label": "My first thought in the silence, and how strongly I believed it:"}, {"id": "f2", "type": "textarea", "label": "What my body did in the first ten seconds:"}, {"id": "f3", "type": "textarea", "label": "Three ordinary reasons a call drops:"}, {"id": "f4", "type": "textarea", "label": "What I did next: called back, waited, or texted, and what happened:"}, {"id": "f5", "type": "textarea", "label": "Who hung up on me in the past, and whether that person is this person:"}]'::jsonb, array['thinking traps', 'thought record', 'relationships']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('thermostat-versus-thermometer-values-page', 'Thermostat Versus Thermometer Values Page', 'act'::resource_kind, 'A page on the difference between reading the room''s temperature and setting it, asking where the client wants to be the thermostat.', 'Use it to help a client who absorbs every mood around them choose one setting where they act from their values, not the room''s weather.', array['Adults', 'Teens']::text[], '20 minutes', 'A thermometer reports the temperature; a thermostat sets it. Clients who describe themselves as sponges for other people''s moods usually live as thermometers everywhere. The page asks where they currently read and match the room (the office, the family dinner, the group chat), what the room''s temperature does to their behavior, and one setting this week where they will choose a temperature from their values and hold it for an hour. It is not about controlling others; a thermostat does not argue with the weather. Watch for a client who turns this into another way to manage everyone.', '[{"id": "f0", "type": "textarea", "label": "The rooms where I am a thermometer: I take the temperature and match it:"}, {"id": "f1", "type": "textarea", "label": "What matching the room costs me, in one honest line:"}, {"id": "f2", "type": "textarea", "label": "The value I would want to set the temperature from, in my own words:"}, {"id": "f3", "type": "textarea", "label": "One room this week where I will be the thermostat for an hour, and what that looks like:"}, {"id": "f4", "type": "textarea", "label": "How I will hold my setting when the room pushes back, without arguing with it:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what the room did, and what I did:"}]'::jsonb, array['values', 'metaphor', 'committed action']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('mind-as-autocomplete-defusion-page', 'Mind as Autocomplete Defusion Page', 'act'::resource_kind, 'A defusion page that treats the mind''s fastest predictions like autocomplete: fast, confident, often wrong, and skippable.', 'Use it to help a client notice the mind finishing their sentences with old endings and type the next word themselves.', array['Adults', 'Teens']::text[], '15 minutes, then a week of noticing', 'Autocomplete guesses the rest of the word from what was typed before; it is quick, confident and frequently wrong, and nobody takes it personally. The page asks the client to collect the mind''s autocompletes for a week (this will go, I always, they are going to) and to notice that each is built from old text, not the present moment. The practice is to see the suggestion, say autocomplete, and type the next word themselves. Watch for a client who tries to turn autocomplete off; it cannot be turned off, only not accepted.', '[{"id": "f0", "type": "textarea", "label": "The sentences my mind finishes before I do, word for word:"}, {"id": "f1", "type": "textarea", "label": "Where the old text comes from: the experiences those endings were built on:"}, {"id": "f2", "type": "textarea", "label": "One autocomplete I accepted this week without noticing, and where it took me:"}, {"id": "f3", "type": "textarea", "label": "The practice: when I see the suggestion, what I say and what I type instead:"}, {"id": "f4", "type": "textarea", "label": "Three times this week I typed my own next word, and what happened:"}, {"id": "f5", "type": "textarea", "label": "What it is like to let the suggestion sit there unaccepted:"}]'::jsonb, array['defusion', 'metaphor', 'automatic thoughts']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('tour-guide-who-only-shows-the-bad-parts-page', 'Tour Guide Who Only Shows the Bad Parts Page', 'act'::resource_kind, 'A metaphor page in which the mind is a tour guide who steers every visit to the city''s worst corners, and the client is still the visitor.', 'Use it to help a client notice the mind''s selective tour of their life and choose where they walk anyway.', array['Adults', 'Teens']::text[], '20 minutes', 'The mind gives a tour of the client''s life that stops only at the failures, the slights and the places something went wrong, and narrates them as the whole city. The page asks the client to list the stops on the guide''s usual tour, to name three places in the same city the guide never visits, and to plan one walk this week to a part of town the guide skips: a person, an activity, a memory. The guide comes along and keeps talking; the visitor chooses the route. Watch for a client who argues with the guide about each stop; the practice is choosing the route, not winning the argument.', '[{"id": "f0", "type": "textarea", "label": "The stops on my mind''s usual tour of my life:"}, {"id": "f1", "type": "textarea", "label": "The guide''s script at the worst stop, word for word:"}, {"id": "f2", "type": "textarea", "label": "Three places in the same city the guide never takes me:"}, {"id": "f3", "type": "textarea", "label": "One walk this week to a part of town the guide skips, and when:"}, {"id": "f4", "type": "textarea", "label": "What the guide said on the way there, and what I did anyway:"}, {"id": "f5", "type": "textarea", "label": "What I noticed at the stop the guide never shows:"}]'::jsonb, array['defusion', 'metaphor', 'values']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('rearview-mirror-driving-metaphor-page', 'Rearview Mirror Driving Metaphor Page', 'act'::resource_kind, 'A page on driving with eyes fixed on the rearview mirror, for the client whose attention lives in what already happened.', 'Use it to help a client notice how often they steer by the past and practice glancing back while looking ahead.', array['Adults', 'Teens']::text[], '15 minutes', 'The rearview mirror is useful; driving by it is not. The page asks the client to notice how much of a typical day is spent looking backward (the conversation replayed, the mistake re-examined, the version of events rewritten), what they miss on the road ahead while doing it, and what a glance looks like instead of a stare. It is not an argument against reflection, which is a glance, but against driving by the mirror. Watch for a client who turns this into never thinking about the past; the mirror stays on the car.', '[{"id": "f0", "type": "textarea", "label": "How much of a typical day I spend looking in the mirror, in an honest estimate:"}, {"id": "f1", "type": "textarea", "label": "What I am usually looking at back there:"}, {"id": "f2", "type": "textarea", "label": "What I have missed on the road ahead while staring at it, this week:"}, {"id": "f3", "type": "textarea", "label": "What a glance at the past looks like, compared to a stare:"}, {"id": "f4", "type": "textarea", "label": "The direction I actually want to drive, in a line from my values:"}, {"id": "f5", "type": "textarea", "label": "One moment this week I noticed the stare and looked back at the road, and what I saw:"}]'::jsonb, array['metaphor', 'mindfulness', 'self-as-context']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('compost-pile-metaphor-for-hard-experiences-page', 'Compost Pile Metaphor for Hard Experiences Page', 'act'::resource_kind, 'A page on hard experiences as compost, asking what has been sitting in the pile and what has quietly turned into soil.', 'Use it to help a client hold a painful history as something that can feed what grows next without pretending it did not hurt.', array['Adults', 'Teens']::text[], '25 minutes', 'Compost is not a happy metaphor and that is why it works: the scraps are real waste, the pile smells for a while, and nobody is asked to enjoy it. The page asks the client to name what is in the pile, what in their life has already turned into soil (the patience, the eye for other people''s pain, the clear sense of what matters), and what they would plant in it. It does not ask them to be grateful for the waste. Watch for a client who hears this as a demand to find a silver lining; the pile is allowed to just be a pile for now, and the page can stop at the first two rows.', '[{"id": "f0", "type": "textarea", "label": "What is in the pile, named without detail:"}, {"id": "f1", "type": "textarea", "label": "What has quietly turned into soil already: a strength, a sensitivity, a clarity I did not have before:"}, {"id": "f2", "type": "textarea", "label": "What I would plant in it, if I chose to:"}, {"id": "f3", "type": "textarea", "label": "What the pile still smells like on a bad day, and what I do on those days:"}, {"id": "f4", "type": "textarea", "label": "One line to myself about not having to be grateful for the waste:"}]'::jsonb, array['acceptance', 'metaphor', 'values']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-shame-that-does-not-fit-the-facts-card', 'Opposite Action for Shame That Does Not Fit the Facts Card', 'dbt'::resource_kind, 'A card for checking whether shame fits the facts and, when it does not, acting opposite to the urge to hide.', 'Use it to help a client whose shame urges them to disappear check the facts and, when shame is unjustified, stay visible on purpose.', array['Adults', 'Teens']::text[], '15 minutes, then in the moment', 'Shame''s action urge is to hide, and hiding is what keeps unjustified shame alive. The card walks the check the facts question (would this group actually reject me for this if they knew), then, when the answer is no, the opposite action: tell someone who will not reject me, keep eye contact, keep the voice at normal volume, do not apologize for existing. When shame does fit the facts (the group really would reject it and the client wants to stay), the card says so and points to repair instead. Watch for a client who checks the facts with the harshest imagined audience; name the actual group.', '[{"id": "f0", "type": "textarea", "label": "The moment the shame arrived, and what it urged me to do:"}, {"id": "f1", "type": "textarea", "label": "The facts: would the people I actually live among reject me for this if they knew:"}, {"id": "f2", "type": "textarea", "label": "If no: the opposite action I will take, including posture, voice and eye contact:"}, {"id": "f3", "type": "textarea", "label": "Who I will tell, and what I will say in one plain sentence:"}, {"id": "f4", "type": "textarea", "label": "If yes: the repair I can make, and the group that would not reject me:"}, {"id": "f5", "type": "textarea", "label": "What happened when I acted opposite, and what the shame did over the next hour:"}]'::jsonb, array['opposite action', 'emotion regulation', 'shame']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('self-soothe-menu-for-the-office-desk-drawer-card', 'Self-Soothe Menu for the Office Desk Drawer Card', 'dbt'::resource_kind, 'A self-soothe card for the workday, listing one item for each sense that fits in a desk drawer or a bag under the desk.', 'Use it to help a client build a small soothing kit they can reach in a bad hour at work without leaving their seat.', array['Adults']::text[], '15 minutes to build, then as needed', 'Self-soothing at work has to be invisible and fast. The card asks for one item per sense that can live in a desk drawer: a photograph or a small object to look at, a tea or a mint to taste, a hand cream or a sachet to smell, a smooth stone or a soft cloth to touch, a single track with headphones to hear. The client also names the minute they will use it (after the hard call, before the meeting) so the kit is not just a drawer. Watch for a client who stocks the drawer and never opens it; the trigger moment matters more than the contents.', '[{"id": "f0", "type": "textarea", "label": "Sight: the small thing I will keep in the drawer to look at for thirty seconds:"}, {"id": "f1", "type": "textarea", "label": "Taste: what I will keep that takes a minute to finish:"}, {"id": "f2", "type": "textarea", "label": "Smell: the sachet, cream or oil that lives there:"}, {"id": "f3", "type": "textarea", "label": "Touch: the object I can hold under the desk without anyone noticing:"}, {"id": "f4", "type": "textarea", "label": "Sound: the one track, and where the headphones live:"}, {"id": "f5", "type": "textarea", "label": "The moments at work when I will actually open the drawer:"}]'::jsonb, array['self-soothing', 'distress tolerance', 'work']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-others-at-the-family-reunion-card', 'Mindfulness of Others at the Family Reunion Card', 'dbt'::resource_kind, 'A card for practicing DBT mindfulness of others at a big family gathering: observing, describing and participating.', 'Use it to help a client walk into a family gathering with a plan to notice the people in front of them instead of the script in their head.', array['Adults']::text[], '10 minutes before, then the event', 'Family gatherings run on old scripts, and clients walk in already knowing what everyone will say. Mindfulness of others asks them to observe with interest instead (what is this cousin actually like this year), to describe what they notice without judgment, and to participate in the conversation that is happening rather than the rehearsed one. The card gives one relative to practice on, one question to ask with real curiosity, and one judgment to catch and rewrite as a description. Watch for a client using it to tolerate someone unsafe; that calls for a safety plan instead.', '[{"id": "f0", "type": "textarea", "label": "The relative I will practice on, and the script I already have about them:"}, {"id": "f1", "type": "textarea", "label": "One question I will ask them with real curiosity, not as a test:"}, {"id": "f2", "type": "textarea", "label": "A judgment I expect to make, and the plain description I will swap in:"}, {"id": "f3", "type": "textarea", "label": "How I will participate in the conversation that is actually happening:"}, {"id": "f4", "type": "textarea", "label": "Afterward: one thing I noticed about this person that I did not know:"}, {"id": "f5", "type": "textarea", "label": "What it was like to be at the gathering as it was rather than as I predicted:"}]'::jsonb, array['mindfulness', 'interpersonal effectiveness', 'family']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('wise-mind-before-lending-the-car-card', 'Wise Mind Before Lending the Car Card', 'dbt'::resource_kind, 'A wise mind card for a request to borrow something that matters, pausing between the yes that avoids conflict and the no that feels mean.', 'Use it to help a client find the answer they can live with when a friend or relative asks to borrow the car, the money or the apartment.', array['Adults', 'Teens']::text[], '10 minutes', 'Lending requests land clients in reasonable mind (the rules say no) or emotion mind (I cannot bear to disappoint them) and most say yes before the pause. The card slows it down: what emotion mind says, what reasonable mind says, the breath, and the question to wise mind: what answer will I still be at peace with next week. It also writes the sentence for a no and a yes with conditions, since both are allowed. Watch for a client whose wise mind always lands on yes; ask what they would advise a friend with the same car.', '[{"id": "f0", "type": "textarea", "label": "The request, who made it, and what I felt in the first second:"}, {"id": "f1", "type": "textarea", "label": "What emotion mind says, in its own words:"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind says, in its own words:"}, {"id": "f3", "type": "textarea", "label": "After a slow breath: what will I still be at peace with next week:"}, {"id": "f4", "type": "textarea", "label": "The sentence for a no, and the sentence for a yes with conditions:"}, {"id": "f5", "type": "textarea", "label": "The answer I gave, and how it sat a week later:"}]'::jsonb, array['wise mind', 'boundaries', 'decisions']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('half-smile-while-waiting-in-traffic-card', 'Half Smile While Waiting in Traffic Card', 'dbt'::resource_kind, 'A card for practicing the half smile and willing hands at red lights and in standstill traffic, where nothing can be done but wait.', 'Use it to give a client a daily place to practice reality acceptance with the body, in a situation that reliably invites resistance.', array['Adults']::text[], 'Every red light for a week', 'Traffic is a perfect practice ground because the client cannot change it and reliably fights it anyway. The card asks for the half smile (lips relaxed, corners turned up barely) and willing hands (palms open on the wheel or the lap) at every red light for a week, with a one-word note at the end of each drive about what the body did. Many clients discover the clench in their jaw and shoulders for the first time this way. Watch for a client who treats the half smile as pretending to be happy; it is the body''s way of signaling acceptance, not approval of the traffic.', '[{"id": "f0", "type": "textarea", "label": "Where I usually drive, and the spots where I fight the traffic most:"}, {"id": "f1", "type": "textarea", "label": "What my jaw, hands and shoulders do at a red light right now:"}, {"id": "f2", "type": "textarea", "label": "The half smile, in my own words, so I remember what it is and is not:"}, {"id": "f3", "type": "textarea", "label": "Willing hands on the wheel: what I will do with my palms:"}, {"id": "f4", "type": "textarea", "label": "One word at the end of each drive this week about what the body did:"}, {"id": "f5", "type": "textarea", "label": "After a week: what changed about the drive, if anything, and what did not:"}]'::jsonb, array['radical acceptance', 'half smile', 'distress tolerance']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('streaming-show-watch-together-pact-for-partners', 'Streaming Show Watch Together Pact for Partners', 'couples'::resource_kind, 'An agreement for the show a couple watches together: when it is watched, whether anyone may watch ahead, and what happens if someone does.', 'Use it to let a couple settle a small recurring quarrel about shared shows and notice what the quarrel is really about.', array['Couples']::text[], '15 minutes', 'The shared show is a small ritual, and watching ahead breaks it in a way that surprises the partner who did it. The pact has each partner say what the show means to them (time together, the only hour we sit down, I just like the show), whether watching ahead is allowed, how a skipped week is handled, and the repair sentence if someone slips. Underneath, it is a conversation about rituals of connection and about being chosen. Watch for a partner who says it does not matter at all while clearly hurt; ask what the hour on the couch does for them.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what our shared show actually means to me, in one honest line:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what our shared show actually means to me, in one honest line:"}, {"id": "f2", "type": "textarea", "label": "Our rule on watching ahead, and what counts as ahead:"}, {"id": "f3", "type": "textarea", "label": "What happens to the ritual on a week one of us is away or working late:"}, {"id": "f4", "type": "textarea", "label": "The repair sentence if one of us slips, and what the other says back:"}, {"id": "f5", "type": "textarea", "label": "One other small ritual we have that we did not know was a ritual until now:"}]'::jsonb, array['couples', 'rituals', 'connection']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('holiday-card-and-gift-list-division-sheet-for-partners', 'Holiday Card and Gift List Division Sheet for Partners', 'couples'::resource_kind, 'A sheet for splitting the holiday list between partners by name, budget and deadline, so one partner does not carry December alone.', 'Use it to make the invisible December load visible to both partners and divide it before the resentment arrives.', array['Couples']::text[], '30 minutes in early December', 'In many couples one partner holds the entire holiday list in their head: whose card, whose gift, which family gets what, which deadline is Friday. The sheet writes the list out, has each partner claim names, agrees on a budget per person, and sets the handoff for anything shared. Each partner also says what part of the season they actually enjoy and want to keep. Watch for the partner who has always done it taking it all back because the other does it differently; the sheet needs a line about whose standard applies to whose names.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the names, cards and gifts I will own this year, with their deadlines:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the names, cards and gifts I will own this year, with their deadlines:"}, {"id": "f2", "type": "textarea", "label": "The budget per person we agree on, and who tracks the total:"}, {"id": "f3", "type": "textarea", "label": "Whose standard applies: if I own a name, I choose the gift, and the other partner says nothing or says what:"}, {"id": "f4", "type": "textarea", "label": "Partner A: the part of the season I actually enjoy and want protected:"}, {"id": "f5", "type": "textarea", "label": "Partner B: the part of the season I actually enjoy and want protected:"}]'::jsonb, array['couples', 'fairness', 'planning']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('morning-alarm-snooze-pact-for-partners', 'Morning Alarm Snooze Pact for Partners', 'couples'::resource_kind, 'An agreement about alarms in a shared bed: how many snoozes, whose alarm wakes whom, and what each partner needs in the first ten minutes.', 'Use it to end a daily friction about alarms and let partners say what the start of the day costs each of them.', array['Couples']::text[], '15 minutes', 'The snooze fight happens at the worst hour and is never resolved because both partners are half asleep. The pact moves it to daylight: how many snoozes are fair, whether the early riser''s alarm can be a vibration, what the late sleeper needs to not be woken twice, and what each partner wants in the first ten minutes of the day (silence, a word, a hand on the back). It also names the mornings the deal is off (a shift change, a sick child). Watch for contempt in how each describes the other''s morning self; that is the thing to work on.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what the first ten minutes of my day are like, and what I need in them:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what the first ten minutes of my day are like, and what I need in them:"}, {"id": "f2", "type": "textarea", "label": "Our alarm rules: how many snoozes, what sound, and whose phone is where:"}, {"id": "f3", "type": "textarea", "label": "What the one who is awake first does so the other is not woken twice:"}, {"id": "f4", "type": "textarea", "label": "The mornings when the deal is off, and how we tell each other:"}, {"id": "f5", "type": "textarea", "label": "The sentence we each use instead of the grumble, in daylight words:"}]'::jsonb, array['couples', 'sleep', 'routines']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('grocery-list-and-shopping-trip-roles-sheet-for-partners', 'Grocery List and Shopping Trip Roles Sheet for Partners', 'couples'::resource_kind, 'A sheet for the weekly grocery run: who keeps the list, who shops, what counts as a substitution, and how the budget conversation goes.', 'Use it to defuse the recurring quarrel about the wrong brand and the forgotten item by making the roles explicit.', array['Couples']::text[], '20 minutes', 'Groceries are a weekly test of whether partners trust each other with small decisions. The sheet asks who keeps the running list and where it lives, who shops and when, what the shopper may substitute without a text, how the forgotten item is handled, and what each partner wants the other to stop saying about the receipt. Underneath is a conversation about standards and control, kept at the scale of a loaf of bread. Watch for the partner who rewrites the list after the other has shopped; name whose kitchen rules apply on whose turn.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what bothers me most about how we handle groceries, said without blame:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what bothers me most about how we handle groceries, said without blame:"}, {"id": "f2", "type": "textarea", "label": "Where the list lives, who adds to it, and the cutoff time before a shop:"}, {"id": "f3", "type": "textarea", "label": "What the shopper may substitute without asking, and what needs a text:"}, {"id": "f4", "type": "textarea", "label": "How we handle the forgotten item and the receipt, in one agreed line each:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: what is easier, and what we still need to settle:"}]'::jsonb, array['couples', 'fairness', 'communication']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('sleeping-in-turn-taking-agreement-for-partners', 'Sleeping In Turn Taking Agreement for Partners', 'couples'::resource_kind, 'An agreement for parents or shift workers about who gets to sleep in on which weekend morning, and what the awake partner handles.', 'Use it to turn the silent contest over weekend sleep into a schedule both partners agreed to in daylight.', array['Couples']::text[], '15 minutes', 'When sleep is scarce, weekend mornings become a quiet competition, and the partner who gets up usually keeps score. The agreement sets who sleeps in on Saturday and who on Sunday, what time sleeping in ends, what the awake partner handles (kids, dog, breakfast, quiet), and how a swap is requested. Each partner also says what an extra hour of sleep is actually worth to them, since for one it may be worth less than an evening alone. Watch for a partner who gives up their turn every week and resents it; the sheet asks them to take it.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what an extra hour of sleep is worth to me, compared to an hour alone in the evening:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the same, in my own words:"}, {"id": "f2", "type": "textarea", "label": "Who sleeps in Saturday, who Sunday, and what time it ends:"}, {"id": "f3", "type": "textarea", "label": "What the awake partner handles, and what they are allowed to leave for later:"}, {"id": "f4", "type": "textarea", "label": "How we request a swap, and how we say no to one:"}, {"id": "f5", "type": "textarea", "label": "After a month: whether the score-keeping quieted down, and what else changed:"}]'::jsonb, array['couples', 'sleep', 'fairness']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('feelings-soup-pot-craft', 'Feelings Soup Pot Craft', 'kids'::resource_kind, 'A paper cooking pot a child fills with ingredient cards for the feelings in a mixed-up day, stirred and named with a parent.', 'Use it to help a child see that several feelings can be in the same pot at once and name each one as it goes in.', array['Children']::text[], '30 minutes', 'The child draws or cuts out a big pot and a set of ingredient cards: a carrot for happy, an onion for the feeling that makes you cry, a chili for angry, a noodle for wiggly or excited, and whatever else they invent. At the end of a day they drop in what was in the soup and stir with a paper spoon. The parent''s part is to add their own ingredients to the same pot and to say, out loud, that a soup can have onion and carrot at once. Keep the pot on the fridge; the soup changes daily, and that is the lesson. Watch for a child who only ever adds one ingredient; model a mixed pot yourself.', '[{"id": "f0", "type": "textarea", "label": "Draw your soup pot and give it a name:"}, {"id": "f1", "type": "textarea", "label": "Draw an ingredient for each feeling you know, and write what each one is:"}, {"id": "f2", "type": "textarea", "label": "What went in the soup today, and what order did it go in:"}, {"id": "f3", "type": "textarea", "label": "Grown-up: what went in your soup today:"}, {"id": "f4", "type": "textarea", "label": "Stir it up: can two very different ingredients be in the same soup at the same time:"}, {"id": "f5", "type": "textarea", "label": "What would make tomorrow''s soup taste a little different:"}]'::jsonb, array['children', 'emotion identification', 'craft']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('feather-float-slow-breath-play', 'Feather Float Slow Breath Play', 'kids'::resource_kind, 'A breathing game in which a child keeps a feather in the air with slow breaths, learning that a soft long breath beats a hard puff.', 'Use it to teach a slow out-breath to a child who cannot yet follow counting instructions.', array['Children']::text[], '10 minutes', 'Hand the child a feather (or a tissue scrap) and the single rule: keep it off the floor using only your breath. Hard puffs send it away and down; a long soft breath keeps it floating. Children discover the slow breath by themselves within a minute, which beats any instruction. The parent plays too, and the two take turns being the one who floats the feather while the other counts how long it stays up. Afterward, ask the child when a long soft breath might help at home. Watch for a child who gets frustrated and starts blowing harder; make it a two-person float so they are not alone with it.', '[{"id": "f0", "type": "textarea", "label": "How long did your feather stay in the air with a hard puff:"}, {"id": "f1", "type": "textarea", "label": "How long with a slow soft breath:"}, {"id": "f2", "type": "textarea", "label": "Grown-up: how long did yours stay up, and which breath did you use:"}, {"id": "f3", "type": "textarea", "label": "Where in your body do you feel the slow breath:"}, {"id": "f4", "type": "textarea", "label": "When at home might a slow feather breath help you:"}, {"id": "f5", "type": "textarea", "label": "Draw your feather and the breath that keeps it up:"}]'::jsonb, array['children', 'breathing', 'play']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('hand-tracing-five-favorite-things-craft', 'Hand Tracing Five Favorite Things Craft', 'kids'::resource_kind, 'A traced hand with one favorite thing on each finger, decorated with a parent, for a child who needs a quick reminder of what is good.', 'Use it to give a child a reminder of five good things that fits on one page and can be made again as the favorites change.', array['Children']::text[], '20 minutes', 'The child traces their hand, and each finger gets one favorite: a person, a food, a place, a thing to do, and a thing they are good at. They decorate each finger to match and the palm gets a drawing of a day that would have all five in it. The parent traces their own hand on the same page or the back and fills in theirs, which tells the child that grown-ups have favorites too. The hand goes somewhere the child sees it at a low moment. Watch for a child who struggles to fill the thumb (a thing I am good at); offer two or three and let them choose.', '[{"id": "f0", "type": "textarea", "label": "Trace your hand. Thumb: a person who is a favorite:"}, {"id": "f1", "type": "textarea", "label": "Pointer finger: a favorite food or snack:"}, {"id": "f2", "type": "textarea", "label": "Middle finger: a favorite place:"}, {"id": "f3", "type": "textarea", "label": "Ring finger: a favorite thing to do:"}, {"id": "f4", "type": "textarea", "label": "Little finger: something you are good at:"}, {"id": "f5", "type": "textarea", "label": "Palm: draw a day that has all five in it. Grown-up: trace your hand too and fill in yours:"}]'::jsonb, array['children', 'strengths', 'craft']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('paper-cup-string-telephone-quiet-talk-play', 'Paper Cup String Telephone Quiet Talk Play', 'kids'::resource_kind, 'Two paper cups and a string, built with a parent, for saying something quietly that is hard to say out loud across a room.', 'Use it to give a child a playful, low-pressure channel for telling a parent about a worry or a feeling.', array['Children']::text[], '30 minutes to build, then as needed', 'Two paper cups, a long string, and a knot through each bottom make a telephone that only works when the string is tight and the room is quiet, so the two players have to cooperate before anything can be said. Build it together, test it with silly messages, then introduce the real rule: either of you can pick up the phone to say one thing that is easier to whisper than to say across the kitchen. The parent goes first with something small and true. Keep the phone somewhere reachable. Watch for a child who only sends silly messages; that is fine, and the channel is open when they need it.', '[{"id": "f0", "type": "textarea", "label": "Build it: what did you need to do so the telephone worked:"}, {"id": "f1", "type": "textarea", "label": "Send a silly message first. What did you say, and what did your grown-up say back:"}, {"id": "f2", "type": "textarea", "label": "Grown-up: say one small true thing through the phone first:"}, {"id": "f3", "type": "textarea", "label": "Now you: one thing that is easier to whisper than to say out loud:"}, {"id": "f4", "type": "textarea", "label": "Where will the telephone live so you can reach it:"}, {"id": "f5", "type": "textarea", "label": "Draw the two of you using it:"}]'::jsonb, array['children', 'communication', 'craft']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('pipe-cleaner-feelings-creatures-craft', 'Pipe Cleaner Feelings Creatures Craft', 'kids'::resource_kind, 'Bendable pipe cleaner creatures for each big feeling, posed and reposed with a parent to show how a feeling can change shape.', 'Use it to let a child give a feeling a body that can be bent into a calmer shape.', array['Children']::text[], '25 minutes', 'The child twists a creature out of pipe cleaners for a feeling (a spiky angry one, a curled-up worried one, a floppy sad one) and gives it a name. Then comes the point of the activity: the creature can be bent. The parent asks what the angry creature looks like after a drink of water and a hug, and the child reposes it. The creatures live in a jar, and at a hard moment the child can pick one and bend it to how the feeling is right now. Watch for a child who wants to destroy the angry creature; instead, ask what it would look like once it has calmed down.', '[{"id": "f0", "type": "textarea", "label": "Make a creature for a feeling you had this week. What is its name, and what shape is it in:"}, {"id": "f1", "type": "textarea", "label": "What does it look like when the feeling is at its biggest:"}, {"id": "f2", "type": "textarea", "label": "Bend it: what does it look like after a drink of water, a hug or a break:"}, {"id": "f3", "type": "textarea", "label": "Grown-up: make a creature for one of your feelings too, and bend it:"}, {"id": "f4", "type": "textarea", "label": "Which creature is in the jar most often:"}, {"id": "f5", "type": "textarea", "label": "Draw your creature in its big shape and its calm shape:"}]'::jsonb, array['children', 'emotion regulation', 'craft']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('tower-of-compliments-cup-stack-game', 'Tower of Compliments Cup Stack Game', 'game'::resource_kind, 'A group game in which each paper cup added to a shared tower carries a specific compliment for another player, and the tower must stand.', 'Use it to get a group giving specific, behavior-based appreciation while cooperating on something that can fall down.', array['Groups']::text[], '25 minutes', 'Each player gets five paper cups and a marker. On a turn, the player writes a compliment on a cup for someone else in the circle (specific, about something they did or said in the group, not about looks) and adds the cup to the shared tower. If the tower falls, everyone rebuilds it together and the game continues until every cup is placed or time is up. Debrief: which compliment surprised you, what was hard about writing one for someone you know less, and what did the tower teach you about building something together. Watch for vague compliments (you are nice); ask for the behavior.', '[{"id": "f0", "type": "textarea", "label": "A compliment you gave: who it was for and what they did:"}, {"id": "f1", "type": "textarea", "label": "A compliment you received that you did not expect:"}, {"id": "f2", "type": "textarea", "label": "What was hard about writing one for someone you know less well:"}, {"id": "f3", "type": "textarea", "label": "When the tower fell, what did the group do, and who started rebuilding:"}, {"id": "f4", "type": "textarea", "label": "One thing about building together you will take out of the room:"}]'::jsonb, array['group', 'appreciation', 'game']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('desert-island-three-items-values-game', 'Desert Island Three Items Values Game', 'game'::resource_kind, 'A group game where each player picks three items for a desert island, defends them, then names the value behind each choice.', 'Use it to get a group talking about what matters to them through a classic choice game with a values debrief.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Each player writes three items they would bring to a desert island (no boats, no phones with signal) and the group takes turns presenting them. After each presentation, the group guesses what the choices say about what the player values; the player confirms or corrects. Round two: each player may trade one item with another player, if both agree. Debrief: which item was hardest to give up, what value was under it, and whether that value gets enough time in your actual week. Watch for players who choose only survival items; ask what they would bring for the evenings.', '[{"id": "f0", "type": "textarea", "label": "Your three items, and the one you would fight hardest to keep:"}, {"id": "f1", "type": "textarea", "label": "What the group guessed your items said about you, and whether they were right:"}, {"id": "f2", "type": "textarea", "label": "The value under your hardest-to-give-up item:"}, {"id": "f3", "type": "textarea", "label": "Did you trade, and what did it take to agree:"}, {"id": "f4", "type": "textarea", "label": "Does that value get enough time in your actual week:"}]'::jsonb, array['group', 'values', 'game']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('alphabet-movement-spell-your-name-game', 'Alphabet Movement Spell Your Name Game', 'game'::resource_kind, 'A movement game in which every letter has an action and players spell their names, then a feeling word, with their whole bodies.', 'Use it to get a group out of their chairs and attending to the present moment before harder work.', array['Groups']::text[], '15 minutes', 'Post a chart that gives each letter of the alphabet a simple action (A is a stretch up, B is a squat, C is a spin, and so on). Players spell their first name with the actions in turn, then the group spells a feeling word someone chooses, letter by letter together. Round three: each player spells a word for how they feel right now and the group guesses the word from the movements. Debrief: what did your body notice, and how is your attention compared to ten minutes ago. Watch for players who sit it out; give them the job of calling the letters.', '[{"id": "f0", "type": "textarea", "label": "The feeling word the group spelled together:"}, {"id": "f1", "type": "textarea", "label": "The word you spelled for how you feel right now, and whether the group guessed it:"}, {"id": "f2", "type": "textarea", "label": "What your body noticed while spelling:"}, {"id": "f3", "type": "textarea", "label": "How your attention is now compared with ten minutes ago:"}, {"id": "f4", "type": "textarea", "label": "Which letter''s action you would put in your day as a one-second reset:"}]'::jsonb, array['group', 'attention', 'game']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('guess-the-sound-listening-circle-game', 'Guess the Sound Listening Circle Game', 'game'::resource_kind, 'A listening game: one player makes an everyday sound out of sight and the circle, eyes closed, names it and the feeling it stirs.', 'Use it to sharpen a group''s attention to sound and open a conversation about how ordinary noises land on each person.', array['Groups']::text[], '20 minutes', 'Collect a bag of everyday objects (keys, a zipper, a crinkly wrapper, a cup of water, a pen clicking). The sound-maker stands behind a screen or the circle closes its eyes; the sound is made once, and the group guesses. The second part is the point: each listener says what the sound brought up for them, in one word. The same jingle of keys means someone coming home for one person and someone leaving for another. Debrief: which sounds did people hear differently, and which everyday sounds at home carry a feeling. Watch for a sound that lands hard on someone; pause and give them the next turn.', '[{"id": "f0", "type": "textarea", "label": "A sound you guessed right, and one you got wrong:"}, {"id": "f1", "type": "textarea", "label": "The sound that brought up the most feeling for you, and the one word:"}, {"id": "f2", "type": "textarea", "label": "A sound that meant different things to two people in the room:"}, {"id": "f3", "type": "textarea", "label": "An everyday sound at home that carries a feeling for you:"}, {"id": "f4", "type": "textarea", "label": "What it was like to listen with your eyes closed in a room of people:"}]'::jsonb, array['group', 'mindfulness', 'game']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('memory-tray-observation-game', 'Memory Tray Observation Game', 'game'::resource_kind, 'An observation game: a tray of objects is shown for thirty seconds and covered, the group lists what it saw, then looks again mindfully.', 'Use it to show a group how attention changes what they remember, with a debrief about where attention goes on a hard day.', array['Groups']::text[], '20 minutes', 'Arrange twelve to fifteen small objects on a tray, show it for thirty seconds while the group talks, then cover it and have each player list what they saw. Round two uses a new tray and thirty seconds of silence with the single instruction to look at each object once. Compare the counts. Debrief: what happened to recall when attention was given on purpose, what pulled your attention away in round one, and where your attention tends to go on a hard day. Watch for players who turn it into a competition; the comparison that matters is each person''s own two rounds.', '[{"id": "f0", "type": "textarea", "label": "Round one: how many objects you remembered, and what pulled your attention away:"}, {"id": "f1", "type": "textarea", "label": "Round two: how many you remembered after looking on purpose:"}, {"id": "f2", "type": "textarea", "label": "What was different in your body and mind during the silent look:"}, {"id": "f3", "type": "textarea", "label": "Where your attention tends to go on a hard day:"}, {"id": "f4", "type": "textarea", "label": "One place this week you could give something thirty seconds of real looking:"}]'::jsonb, array['group', 'attention', 'mindfulness']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('smells-that-pull-me-back-inventory-and-anchor-sheet', 'Smells That Pull Me Back Inventory and Anchor Sheet', 'worksheet'::resource_kind, 'An inventory of the smells that drag a client into the past, paired with a present-day scent anchor and a plan for the places they turn up.', 'Use it to help a client map scent reminders and prepare a steadying smell they carry, without revisiting what the smells are tied to.', array['Adults']::text[], '25 minutes in session', 'Smell is the sense that bypasses the present fastest, and most clients have never listed theirs. The sheet asks for the smells that pull them back (named only as smells: diesel, a cologne, a hospital corridor), where those are likely to show up, and a present-day anchor scent they choose and carry: a lip balm, a sachet, a coffee bean in a pocket. The practice is to notice the pull, reach for the anchor, and say today''s date. Do it in session, not as homework; the sheet never asks what the smells are tied to. Watch for a client who starts narrating the memory; return to the anchor.', '[{"id": "f0", "type": "textarea", "label": "Smells that pull me back, named only as smells:"}, {"id": "f1", "type": "textarea", "label": "Places and times those smells are likely to show up this month:"}, {"id": "f2", "type": "textarea", "label": "The present-day scent I choose as my anchor, and where I will carry it:"}, {"id": "f3", "type": "textarea", "label": "What I say to myself as I reach for the anchor:"}, {"id": "f4", "type": "textarea", "label": "Who I can tell that a smell got me, in one sentence that needs no detail:"}, {"id": "f5", "type": "textarea", "label": "After a week: a time the anchor helped, or a time it was not enough and what I did:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'triggers']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('numb-means-broken-thought-check-sheet', 'Numb Means Broken Thought Check Sheet', 'cbt'::resource_kind, 'A thought check for the client who reads emotional flatness after trauma as proof that something in them is permanently broken.', 'Use it to help a client question the verdict they attach to numbness and consider it as a response rather than a sentence.', array['Adults']::text[], '20 minutes in session', 'Clients often arrive more troubled by the numbness than by the fear: they feel nothing at a wedding or a funeral and conclude they are ruined. The sheet records the moment, the hot thought (I am broken, I will never feel again, something is wrong with me as a person), the evidence for and against, including every moment in the last month something did get through (a laugh, an irritation, a pang), and a kinder description of what numbness might be doing. Keep it in session. Watch for a client who treats one flat afternoon as the whole picture; the month-long evidence row is the counterweight.', '[{"id": "f0", "type": "textarea", "label": "The moment I noticed the flatness, and what was happening around me:"}, {"id": "f1", "type": "textarea", "label": "The verdict I handed myself about it, word for word:"}, {"id": "f2", "type": "textarea", "label": "Every moment in the last month that something did get through, however small:"}, {"id": "f3", "type": "textarea", "label": "What numbness might be doing for me right now, described without judgment:"}, {"id": "f4", "type": "textarea", "label": "A kinder, more accurate sentence about the flat afternoon:"}, {"id": "f5", "type": "textarea", "label": "What I would say to a friend who told me they felt nothing at their own party:"}]'::jsonb, array['PTSD and trauma', 'thinking traps', 'self-talk']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('window-seat-on-the-train-willingness-page', 'Window Seat on the Train Willingness Page', 'act'::resource_kind, 'A willingness page for taking a seat the body says is unsafe, like the window seat with no quick exit, when the client values the trip.', 'Use it to help a client choose a valued seat, trip or room while the body protests, with the protest allowed to come along.', array['Adults']::text[], '20 minutes, then one trip', 'After trauma many clients organize their lives around exits: the aisle seat, the chair facing the door, the car not the train. The page does not argue with any of it. It asks what the exit habit costs (the trip not taken, the friend not visited), the value on the other side, one seat or place this month the client is willing to try while the body protests, and what willing looks like there in behavior: hands open, breath slow, staying ten more minutes. Pace it with the client; this is their choice of step, not a hierarchy you set. Watch for white-knuckling disguised as willingness.', '[{"id": "f0", "type": "textarea", "label": "The exits I arrange my days around, listed without judgment:"}, {"id": "f1", "type": "textarea", "label": "What the exit habit has cost me this year:"}, {"id": "f2", "type": "textarea", "label": "The value on the other side of one of those exits:"}, {"id": "f3", "type": "textarea", "label": "One seat, trip or room I am willing to try this month while my body protests:"}, {"id": "f4", "type": "textarea", "label": "What willing looks like there: my hands, my breath, how long I stay:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what the body did, what I did, and whether I would do it again:"}]'::jsonb, array['PTSD and trauma', 'willingness', 'values']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('observe-and-describe-nightmare-residue-morning-card', 'Observe and Describe Nightmare Residue Morning Card', 'dbt'::resource_kind, 'A mindfulness card for the morning after a nightmare, observing the body''s leftover state and describing it without replaying the dream.', 'Use it to give a client a way to start the day after a bad night that names what the body is carrying without reopening the dream.', array['Adults']::text[], '5 minutes on waking', 'The morning after a nightmare, clients either replay it or try to outrun it, and both keep it going. The card gives the observe and describe skills a specific job: notice the body''s leftover state (heart rate, jaw, the urge to check the room), describe it in plain words (my shoulders are up, my hands are cold), note the date and the room, and choose one ordinary first action. The dream itself is not described on the card. If the client wants to work on the dream, that is a session, not a morning. Watch for a client who writes the dream anyway; move the card to the kitchen, away from the bed.', '[{"id": "f0", "type": "textarea", "label": "Observe: what my body is doing right now, in three plain facts:"}, {"id": "f1", "type": "textarea", "label": "Describe: the room I am in and today''s date, said out loud:"}, {"id": "f2", "type": "textarea", "label": "The urge I notice (to check, to replay, to stay in bed), named and not acted on yet:"}, {"id": "f3", "type": "textarea", "label": "My one ordinary first action: water, curtains, the kettle:"}, {"id": "f4", "type": "textarea", "label": "What I will tell my therapist about the night, in one line, without the dream:"}]'::jsonb, array['PTSD and trauma', 'mindfulness', 'sleep']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('spacing-out-explainer-and-return-cue-sheet-for-partners', 'Spacing Out Explainer and Return Cue Sheet for Partners', 'couples'::resource_kind, 'A partner who spaces out explains what it is like from inside, and the other partner learns a gentle cue that helps them come back.', 'Use it to replace a partner''s alarm or frustration at zoning out with a shared understanding and an agreed way back.', array['Couples']::text[], '30 minutes in session', 'Partners of clients who dissociate often feel shut out or frightened, and their attempts to help (shaking, loud voice, demanding attention) can make returning harder. The sheet has the partner who spaces out describe what it feels like from inside and what they can and cannot hear, and the other partner describe what they see and feel. Together they choose a return cue: the name said softly, a hand offered not grabbed, a question about the room. It does not ask about the history behind it. Watch for a partner who takes it as rejection; name it as the nervous system, not a choice.', '[{"id": "f0", "type": "textarea", "label": "Partner who spaces out: what it is like from inside, and what I can and cannot take in while it happens:"}, {"id": "f1", "type": "textarea", "label": "Partner who watches: what I see, and what I feel while it happens:"}, {"id": "f2", "type": "textarea", "label": "The return cue we agree on: words, touch, or a question about the room:"}, {"id": "f3", "type": "textarea", "label": "What does not help, said plainly so neither of us guesses:"}, {"id": "f4", "type": "textarea", "label": "What we each do in the ten minutes after a return:"}, {"id": "f5", "type": "textarea", "label": "One line from each of us about what this is and is not about between us:"}]'::jsonb, array['PTSD and trauma', 'couples', 'grounding']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('worry-free-zone-room-designation-sheet', 'Worry-Free Zone Room Designation Sheet', 'worksheet'::resource_kind, 'A sheet for naming one room or spot in the home where worry is not entertained, with what the client does when worry follows them in.', 'Use it to give a client a physical boundary for worry so at least one place in the home stays associated with rest.', array['Adults', 'Teens']::text[], '15 minutes to set up, then two weeks', 'Worry spreads to every room of the house until nowhere feels like rest. The sheet picks one room or spot (the armchair, the bath, the kitchen table at breakfast) and makes it the worry-free zone: worry is not argued with there, it is written on a slip and carried to a designated worry spot elsewhere for later. The client lists what the zone is for instead and what they do when a worry follows them in. Watch for a client who picks the bed as the zone and then lies in it worrying; the zone should be a place they can leave easily.', '[{"id": "f0", "type": "textarea", "label": "The room or spot I name as the worry-free zone, and why that one:"}, {"id": "f1", "type": "textarea", "label": "What this spot is for instead: the activities that belong there:"}, {"id": "f2", "type": "textarea", "label": "Where the worry spot is, and when I visit it on purpose:"}, {"id": "f3", "type": "textarea", "label": "What I do when a worry follows me into the zone:"}, {"id": "f4", "type": "textarea", "label": "The sentence I say to the worry as I carry it out:"}, {"id": "f5", "type": "textarea", "label": "Two weeks in: does the zone feel different from the rest of the house:"}]'::jsonb, array['anxiety', 'worry', 'routines']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('how-bad-will-it-feel-intensity-prediction-sheet', 'How Bad Will It Feel Intensity Prediction Sheet', 'cbt'::resource_kind, 'A sheet that records how bad a client predicts an event will feel, out of ten, and compares it with the actual intensity afterward.', 'Use it to help a client who overestimates distress see the gap between predicted and actual intensity across several events.', array['Adults', 'Teens']::text[], '5 minutes before and after each event, for two weeks', 'Clients often predict not just that something bad will happen but that the feeling will be unbearable, and the second prediction drives the avoidance. The sheet separates them: before an event, rate how bad it will feel and how long it will last; afterward, rate how bad it actually felt and how long it actually lasted. Collect six or more events before drawing any conclusion. Watch for a client who rates afterward from memory a week later; the after rating should be done the same day, and a long-remembered event tends to be rated worse than it was.', '[{"id": "f0", "type": "textarea", "label": "The event I am anticipating, and when it is:"}, {"id": "f1", "type": "textarea", "label": "How bad I predict it will feel, out of ten, and how long I predict the feeling will last:"}, {"id": "f2", "type": "textarea", "label": "The same day: how bad it actually felt, out of ten, and how long it actually lasted:"}, {"id": "f3", "type": "textarea", "label": "Second event: prediction and actual:"}, {"id": "f4", "type": "textarea", "label": "Third event: prediction and actual:"}, {"id": "f5", "type": "textarea", "label": "After six events: the pattern between my predictions and what happened:"}, {"id": "f6", "type": "textarea", "label": "What I will tell myself the next time my mind says it will be unbearable:"}]'::jsonb, array['anxiety', 'predictions', 'self-monitoring']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('anxious-mind-as-a-weather-app-that-always-says-storm-page', 'Anxious Mind as a Weather App That Always Says Storm Page', 'act'::resource_kind, 'A defusion page in which the anxious mind is a weather app stuck on the storm icon, and the client checks the window instead.', 'Use it to help a client notice the mind''s constant storm forecast and act on the day in front of them.', array['Adults', 'Teens']::text[], '15 minutes, then a week of noticing', 'The anxious mind issues a storm warning for every day, and like a broken app it is sometimes right, which keeps the client checking it. The page asks the client to notice the forecast each morning, write it in a word, look out the actual window (the day as it is), and decide what to do by the window rather than the app. The app is not deleted; it keeps running in the corner. Over a week the client collects forecasts and actual weather. Watch for a client who argues with the app about whether the storm is coming; checking the window is a different move than debating.', '[{"id": "f0", "type": "textarea", "label": "This morning''s forecast from my mind, in one word or one sentence:"}, {"id": "f1", "type": "textarea", "label": "What is actually outside the window right now: the day as it is:"}, {"id": "f2", "type": "textarea", "label": "What I will do by the window, not by the app, in the next hour:"}, {"id": "f3", "type": "textarea", "label": "Day by day for a week: forecast, actual weather, what I did:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the app''s accuracy by the end of the week:"}, {"id": "f5", "type": "textarea", "label": "What it is like to let the app run in the corner without opening it:"}]'::jsonb, array['anxiety', 'defusion', 'metaphor']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-reassurance-seeking-card', 'Opposite Action to Reassurance Seeking Card', 'dbt'::resource_kind, 'An opposite action card for the moment a client wants to ask once more if everything is all right, with the action that goes the other way.', 'Use it to give a client a concrete alternative to asking for reassurance when the urge arrives and the fear does not fit the facts.', array['Adults', 'Teens']::text[], '10 minutes, then in the moment', 'Reassurance seeking is an action urge like any other, and opposite action fits it well once the client has checked the facts and found the fear does not justify the ask. The card names the urge (text them again, ask if I did it right, look it up once more), the opposite action (put the phone down, say I will find out later, act as if the answer were fine), and what to do with the anxiety in the meantime. It also includes the honest case where the question is reasonable and should be asked once. Watch for a client who uses the card to suppress legitimate questions; one ask is allowed.', '[{"id": "f0", "type": "textarea", "label": "The reassurance I want to ask for right now, and from whom:"}, {"id": "f1", "type": "textarea", "label": "Check the facts: does the fear fit the situation, and have I already asked once:"}, {"id": "f2", "type": "textarea", "label": "The opposite action: what I will do with my hands and my words instead:"}, {"id": "f3", "type": "textarea", "label": "What I will do with the anxiety for the next twenty minutes:"}, {"id": "f4", "type": "textarea", "label": "If the question is reasonable and unasked: the one time I will ask it, and then stop:"}, {"id": "f5", "type": "textarea", "label": "What happened to the anxiety after the twenty minutes:"}]'::jsonb, array['anxiety', 'opposite action', 'reassurance']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('brave-explorer-cardboard-binoculars-craft', 'Brave Explorer Cardboard Binoculars Craft', 'kids'::resource_kind, 'Cardboard tube binoculars a child decorates and uses to look at something a little scary from a safe distance, with a parent as co-explorer.', 'Use it to help an anxious child look at a feared thing from far away first, in a game they control.', array['Children']::text[], '30 minutes to build, then explorer missions', 'Two cardboard tubes taped together, decorated with stickers and a strap of yarn, become explorer binoculars. The game is that explorers look at things from far away before they go closer, and the child chooses what to look at: the dog across the street, the dark hallway from the lit kitchen, the big slide from the bench. The parent is the co-explorer who looks too, says what they see in plain words, and never pushes for closer. Each mission ends with the explorer''s report. Watch for a parent who turns the binoculars into a push; the child picks the distance.', '[{"id": "f0", "type": "textarea", "label": "Decorate your binoculars and give your explorer team a name:"}, {"id": "f1", "type": "textarea", "label": "Mission one: what will you look at from far away, and from where:"}, {"id": "f2", "type": "textarea", "label": "What did you see through the binoculars, in explorer words:"}, {"id": "f3", "type": "textarea", "label": "Grown-up: what did you see, in plain words, from the same spot:"}, {"id": "f4", "type": "textarea", "label": "Would the explorer like to look from a little closer next time, or the same spot again:"}, {"id": "f5", "type": "textarea", "label": "Draw the thing you looked at, and draw how far away you were:"}]'::jsonb, array['anxiety', 'children', 'craft']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('bed-as-bed-only-daytime-spot-plan-sheet', 'Bed as Bed Only Daytime Spot Plan Sheet', 'worksheet'::resource_kind, 'A plan for moving daytime life out of the bed when low mood has made it the office, the dining room and the couch.', 'Use it to help a client who lives in bed on low days create one other spot in the home and move one activity to it.', array['Adults', 'Teens']::text[], '15 minutes, then one week', 'When mood is low the bed becomes everything, and sleep gets worse while the day gets smaller. The sheet does not ask the client to get out of the house. It asks them to name one other spot (a chair by a window, the kitchen table, the floor with a cushion), make it comfortable in advance, and move one daytime activity there this week: eating, scrolling, the phone call. Bed is kept for sleep and nothing else is forbidden. Watch for a client who sets a rule of never lying down in the day and breaks it on the second afternoon; a nap in the chair is a success.', '[{"id": "f0", "type": "textarea", "label": "Where I spend my daytime hours on a low day, honestly:"}, {"id": "f1", "type": "textarea", "label": "One other spot in my home I could make comfortable, and what it needs (a blanket, a lamp, a charger):"}, {"id": "f2", "type": "textarea", "label": "The one daytime activity I will move to that spot this week:"}, {"id": "f3", "type": "textarea", "label": "What I do with the pull back to bed in the middle of the afternoon:"}, {"id": "f4", "type": "textarea", "label": "A nap or a rest in the new spot counts; what else counts as a success this week:"}, {"id": "f5", "type": "textarea", "label": "After a week: how many days the spot got used, and what the nights were like:"}]'::jsonb, array['depression', 'routines', 'behavioral activation']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('i-have-always-been-like-this-overgeneralization-sheet', 'I Have Always Been Like This Overgeneralization Sheet', 'cbt'::resource_kind, 'A sheet for the client whose low mood rewrites their whole history as low, testing the word always against specific years and seasons.', 'Use it to help a client find the stretches of their life that the current mood has erased from the record.', array['Adults', 'Teens']::text[], '20 minutes', 'Low mood is a historian with an agenda: it reports that the client has always been this way and will always be. The sheet asks for the exact sentence, then walks the years (a timeline, a decade at a time, then the last five years season by season) looking for stretches that do not fit the word always. Most clients find them once asked for specifics rather than impressions. The last rows ask what was different in those stretches and what one piece of that might be borrowed now. Watch for a client who dismisses every good stretch as not counting; write them down anyway.', '[{"id": "f0", "type": "textarea", "label": "The sentence my mood tells me about my whole life, word for word:"}, {"id": "f1", "type": "textarea", "label": "Decade by decade: a stretch in each that does not fit the word always:"}, {"id": "f2", "type": "textarea", "label": "The last five years, season by season: the ones that were not like this:"}, {"id": "f3", "type": "textarea", "label": "What was different in those stretches: people, place, routine, work, sleep:"}, {"id": "f4", "type": "textarea", "label": "One small piece of a better stretch I could borrow this month:"}, {"id": "f5", "type": "textarea", "label": "A more accurate sentence than always, even if it is only slightly more accurate:"}]'::jsonb, array['depression', 'thinking traps', 'overgeneralization']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('quiet-values-beneath-the-flat-feeling-page', 'Quiet Values Beneath the Flat Feeling Page', 'act'::resource_kind, 'A values page for the client who feels nothing and concludes they want nothing, listening for what still stings as a clue to what matters.', 'Use it to help a client in a flat stretch find their values by what still stings rather than by what excites them.', array['Adults', 'Teens']::text[], '25 minutes', 'When mood is flat, the usual values questions (what lights you up, what do you love) get a shrug. The page comes at it sideways: what still annoys you, what you still feel guilty about not doing, who you would be sad to disappoint, what you would be embarrassed to be seen neglecting. Each of these points at a value that is still there under the flatness. The client then names one value found this way and one small action that serves it without needing the feeling first. Watch for a client who reads this as proof they only have negative feelings left; the sting is the value showing itself.', '[{"id": "f0", "type": "textarea", "label": "What still bothers me, even a little, when nothing else does:"}, {"id": "f1", "type": "textarea", "label": "What I feel guilty about not doing, and what that says I care about:"}, {"id": "f2", "type": "textarea", "label": "Who I would be sad to disappoint, and what they are a stand-in for:"}, {"id": "f3", "type": "textarea", "label": "One value I found this way, in my own words:"}, {"id": "f4", "type": "textarea", "label": "One small action that serves it this week, done without waiting to feel like it:"}, {"id": "f5", "type": "textarea", "label": "How the flatness and the action sat together afterward:"}]'::jsonb, array['depression', 'values', 'committed action']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-staying-in-pajamas-all-day-card', 'Opposite Action to Staying in Pajamas All Day Card', 'dbt'::resource_kind, 'An opposite action card for the low day that never gets dressed, with the smallest version of the action that still counts.', 'Use it to give a client a concrete, scaled opposite action for the pull to stay in sleepwear when low mood is running the day.', array['Adults', 'Teens']::text[], '5 minutes in the morning', 'Staying in pajamas is a small action urge that organizes the whole day around withdrawal. The card checks the facts (am I actually ill or resting on purpose, or is this the mood), then sets the opposite action at the size that is possible today: full version is shower and clothes, middle is clothes without the shower, smallest is socks and a different shirt. The client picks the size before the day decides for them. Watch for a client who uses the card to shame themselves for not doing the full version; the smallest size is a real opposite action and counts.', '[{"id": "f0", "type": "textarea", "label": "The pull this morning, named plainly, and whether it is illness, chosen rest, or the mood:"}, {"id": "f1", "type": "textarea", "label": "Full version of the opposite action, and what it would take:"}, {"id": "f2", "type": "textarea", "label": "Middle version, and what it would take:"}, {"id": "f3", "type": "textarea", "label": "Smallest version that still counts, and what it would take:"}, {"id": "f4", "type": "textarea", "label": "The size I choose today, and the time I will do it by:"}, {"id": "f5", "type": "textarea", "label": "What the day did after I did it, even a little:"}]'::jsonb, array['depression', 'opposite action', 'behavioral activation']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('cheer-up-or-keep-company-preference-sheet-for-partners', 'Cheer Up or Keep Company Preference Sheet for Partners', 'couples'::resource_kind, 'A sheet in which a partner with low mood says whether they want cheering up or quiet company, and the other partner learns the difference.', 'Use it to stop the well-meant pep talk that lands as pressure and give both partners a clear menu for low days.', array['Couples']::text[], '20 minutes', 'Partners of someone with low mood often try to fix it with plans, encouragement and gratitude lists, and the low partner ends up managing their partner''s disappointment too. The sheet has the low-mood partner rank what actually helps (sit with me, do a chore beside me, leave me for an hour and come back, distract me, do not ask how I am) and the other partner say what helping does for them and what being told to stop is like. They agree on a signal for which item is wanted today. Watch for the helping partner hearing rejection; separate the help from the helper.', '[{"id": "f0", "type": "textarea", "label": "Partner with low mood: what actually helps on a low day, ranked from most to least:"}, {"id": "f1", "type": "textarea", "label": "Partner with low mood: what is meant kindly but lands as pressure:"}, {"id": "f2", "type": "textarea", "label": "Other partner: what trying to help does for me, and what it is like to be told to stop:"}, {"id": "f3", "type": "textarea", "label": "Our signal for which kind of help is wanted today:"}, {"id": "f4", "type": "textarea", "label": "What the other partner does for themselves when the answer is leave me alone for an hour:"}, {"id": "f5", "type": "textarea", "label": "After two low days: what we each got right, and what we will adjust:"}]'::jsonb, array['depression', 'couples', 'support']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('browser-tab-hoard-cleanup-steps-sheet', 'Browser Tab Hoard Cleanup Steps Sheet', 'worksheet'::resource_kind, 'A step sheet for the eighty open tabs that have become a to-do list the client cannot close, sorting them into done, saved and gone.', 'Use it to help a client with a tab hoard close it in one sitting without losing the few things that matter in it.', array['Adults', 'Teens']::text[], '30 minutes', 'Open tabs are an external working memory that stops working at about twenty. The sheet walks a single cleanup: count the tabs, sort each into three piles (do it now in under two minutes, save it in one named list, close it), set a timer, and finish with a rule for the future, like a maximum count or a Friday close-all. The client also writes what the tabs were protecting them from losing, which is usually the fear of forgetting. Watch for a client who saves everything to a reading list that becomes the new hoard; the save list gets a cap too.', '[{"id": "f0", "type": "textarea", "label": "How many tabs are open right now, counted honestly:"}, {"id": "f1", "type": "textarea", "label": "The two-minute ones: do them now and list what they were:"}, {"id": "f2", "type": "textarea", "label": "The save pile: the one named list they go into, and its cap:"}, {"id": "f3", "type": "textarea", "label": "The close pile: what I am afraid of losing by closing them, and whether that is true:"}, {"id": "f4", "type": "textarea", "label": "My rule for the future: a maximum count, a weekly close-all, or something else:"}, {"id": "f5", "type": "textarea", "label": "A week later: how many tabs are open, and how the rule held:"}]'::jsonb, array['ADHD', 'executive function', 'habits']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('they-think-i-do-not-care-because-i-was-late-thought-record', 'They Think I Do Not Care Because I Was Late Thought Record', 'cbt'::resource_kind, 'A thought record for the shame spiral after lateness, where a client decides their lateness has told everyone they do not care.', 'Use it to help a client separate the practical problem of lateness from the global verdict they attach to it.', array['Adults', 'Teens']::text[], '15 minutes', 'Lateness carries a double load for many clients: the practical cost and the conviction that it has revealed them as careless and unloving. The record captures the lateness, the thought (they think I do not care, I have ruined it), the feeling, the evidence for and against, including what the other person actually said, and a plan that addresses the lateness as a logistics problem rather than a character problem. Watch for a client who skips the logistics row because they are too ashamed; the shame is part of why the pattern continues.', '[{"id": "f0", "type": "textarea", "label": "The lateness: how late, to what, and what happened in the ten minutes before leaving:"}, {"id": "f1", "type": "textarea", "label": "The thought about what it told them about me, word for word:"}, {"id": "f2", "type": "textarea", "label": "What the other person actually said and did when I arrived:"}, {"id": "f3", "type": "textarea", "label": "Evidence that lateness equals not caring, and evidence against it:"}, {"id": "f4", "type": "textarea", "label": "The logistics problem underneath, stated without character words:"}, {"id": "f5", "type": "textarea", "label": "One logistics fix for the next time, and one sentence for the apology that does not grovel:"}]'::jsonb, array['ADHD', 'thinking traps', 'thought record']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('finishing-as-a-direction-not-a-destination-page', 'Finishing as a Direction Not a Destination Page', 'act'::resource_kind, 'A values page for the client who starts everything and finishes nothing, treating finishing as a direction they can face at any moment.', 'Use it to help a client with a pile of unfinished things choose to face toward finishing today without needing to finish everything.', array['Adults', 'Teens']::text[], '20 minutes', 'The unfinished pile shames clients into starting something new, which adds to the pile. The page reframes finishing as a direction like west: you cannot arrive at west, but you can always face it. The client lists the pile without judgment, names what finishing would serve (a value, not a verdict), and picks one thing to face toward today for fifteen minutes, whether or not it gets done. Facing west for fifteen minutes is the whole task. Watch for a client who turns this into a plan to finish all of it this weekend; that is facing the whole compass at once.', '[{"id": "f0", "type": "textarea", "label": "The unfinished pile, listed without a single judgment word:"}, {"id": "f1", "type": "textarea", "label": "What finishing serves for me: the value underneath, not the verdict:"}, {"id": "f2", "type": "textarea", "label": "One thing in the pile I will face toward today, for fifteen minutes:"}, {"id": "f3", "type": "textarea", "label": "What I expect my mind to say at minute three, and what I will do then:"}, {"id": "f4", "type": "textarea", "label": "Afterward: did I face west for fifteen minutes, regardless of whether it got done:"}, {"id": "f5", "type": "textarea", "label": "Tomorrow''s fifteen minutes: the same thing or another, and why:"}]'::jsonb, array['ADHD', 'values', 'committed action']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('dear-man-for-a-deadline-extension-card', 'DEAR MAN for a Deadline Extension Card', 'dbt'::resource_kind, 'A DEAR MAN script for asking a teacher, manager or client for more time, written before the deadline passes rather than after.', 'Use it to help a client make an early, clear request for an extension instead of going silent and missing the date.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients who struggle with deadlines often know a week ahead that they will miss one and say nothing until it is past. DEAR MAN gives the early ask a shape: describe the situation in facts, express what it means for the work, assert the specific new date, reinforce what the other person gets, stay mindful of the goal when they push back, appear confident, and negotiate if the first date is refused. The card is written at least three days before the deadline. Watch for a client who writes a paragraph of apology for the describe line; one sentence of facts.', '[{"id": "f0", "type": "textarea", "label": "Describe: the assignment or deliverable and the current deadline, in facts only:"}, {"id": "f1", "type": "textarea", "label": "Express: what more time would change about the work:"}, {"id": "f2", "type": "textarea", "label": "Assert: the exact new date I am asking for:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what they get from saying yes (better work, no last-minute scramble):"}, {"id": "f4", "type": "textarea", "label": "Mindful and confident: what I will do when they frown or push back:"}, {"id": "f5", "type": "textarea", "label": "Negotiate: the second date I can offer if the first is a no:"}, {"id": "f6", "type": "textarea", "label": "How many days before the deadline I will send this, and how:"}]'::jsonb, array['ADHD', 'DEAR MAN', 'interpersonal effectiveness']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('wiggle-break-spinner-wheel-craft', 'Wiggle Break Spinner Wheel Craft', 'kids'::resource_kind, 'A paper spinner wheel of one-minute movement breaks a child makes with a parent and spins when sitting still has run out.', 'Use it to give a child who needs to move a sanctioned, quick way to do it between tasks, chosen by chance rather than argument.', array['Children']::text[], '25 minutes to make, then daily', 'The child draws a wheel divided into six or eight slices and fills each with a one-minute movement they like: ten jumping jacks, crab walk to the door and back, wall push, animal walk, dance to one song, spin three times. A paper clip or a pencil through the middle makes the spinner. When homework or sitting has run out, the child spins, does the break, and comes back. The parent''s part is to set how many spins a homework session gets, to spin and move too, and never to use the wheel as a reward or punishment. Watch for a wheel filled with sitting-down slices.', '[{"id": "f0", "type": "textarea", "label": "Divide your wheel. Write a one-minute movement in each slice:"}, {"id": "f1", "type": "textarea", "label": "Which slice is your favorite, and which one is hardest:"}, {"id": "f2", "type": "textarea", "label": "Grown-up: how many spins does a homework session get, and where does the wheel live:"}, {"id": "f3", "type": "textarea", "label": "Spin it now and do the break. How did your body feel after:"}, {"id": "f4", "type": "textarea", "label": "What is the signal that it is time to spin instead of wiggling in the chair:"}, {"id": "f5", "type": "textarea", "label": "Draw yourself doing your favorite slice:"}]'::jsonb, array['ADHD', 'children', 'craft']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('holiday-party-exit-time-and-ride-plan-sheet', 'Holiday Party Exit Time and Ride Plan Sheet', 'worksheet'::resource_kind, 'A plan for a holiday party where substances will be around: the arrival, the drink in hand, the exit time and the ride home set in advance.', 'Use it to help a client attend a seasonal event with substances present without improvising the hard moments.', array['Adults']::text[], '20 minutes before the event', 'The holiday party is where many clients'' substance-free streaks end, because the plan was to see how it goes. The sheet decides the key moments beforehand: the arrival time, the non-alcoholic drink that is in hand from the first minute, the person who knows the plan, the answer to why aren''t you drinking, the exit time written on the hand or the phone, and the ride home booked before leaving the house. It also asks what the urge will say at nine o''clock and what the client will do with it. Watch for a client who leaves the exit time blank to stay flexible.', '[{"id": "f0", "type": "textarea", "label": "The event, the arrival time, and the drink that will be in my hand from the first minute:"}, {"id": "f1", "type": "textarea", "label": "The person there who knows my plan, and what I will text them if the urges climb:"}, {"id": "f2", "type": "textarea", "label": "My answer when someone asks why I am not drinking, in one sentence:"}, {"id": "f3", "type": "textarea", "label": "My exit time, and where I will write it so I see it:"}, {"id": "f4", "type": "textarea", "label": "The ride home, booked before I leave the house:"}, {"id": "f5", "type": "textarea", "label": "What the urge will say at nine o''clock, and what I will do with it:"}]'::jsonb, array['addiction', 'substance use', 'planning']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('i-am-not-fun-without-it-thought-record', 'I Am Not Fun Without It Thought Record', 'cbt'::resource_kind, 'A thought record for the belief that the client''s social self depends on a substance, with evidence from times they were fun without it.', 'Use it to help a client test the belief that they are boring or stiff without substances, before the belief decides an evening for them.', array['Adults', 'Teens']::text[], '20 minutes', 'The belief that fun requires the substance is one of the quieter drivers of use, and it is rarely examined because it feels like a fact about personality. The record takes the belief, rates it, and gathers evidence: times in the last year the client laughed, danced or talked easily with nothing in hand; what other people have actually said about them sober; and what the substance actually did to their fun on the nights it went badly. Watch for a client who can find no evidence; walk through childhood and early teens, before the substance was in the picture.', '[{"id": "f0", "type": "textarea", "label": "The belief, word for word, and how much I believe it out of a hundred:"}, {"id": "f1", "type": "textarea", "label": "Times in the last year I was fun or at ease with nothing in my hand:"}, {"id": "f2", "type": "textarea", "label": "What people who know me have actually said about me when I was substance-free:"}, {"id": "f3", "type": "textarea", "label": "What the substance did to my fun on the nights it went badly:"}, {"id": "f4", "type": "textarea", "label": "Who I was at a party before the substance was ever in the picture:"}, {"id": "f5", "type": "textarea", "label": "My belief now, out of a hundred, and what I will test at the next gathering:"}]'::jsonb, array['addiction', 'substance use', 'thought record']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('fifteen-minute-urge-willingness-timer-page', 'Fifteen Minute Urge Willingness Timer Page', 'act'::resource_kind, 'A willingness page that sets a fifteen-minute timer when an urge arrives and asks the client to make room for it, promising nothing after.', 'Use it to help a client stay with an urge for a bounded time instead of fighting it or feeding it.', array['Adults', 'Teens']::text[], '15 minutes, as needed', 'Fighting an urge and giving in to it both end the discomfort fast, and willingness is the slow third option. The page asks the client to set a timer for fifteen minutes when the urge arrives, to describe the urge as a bodily event (where it sits, its temperature, how it moves), to say what the mind is promising, and to do one small valued thing with their hands while the urge is present. At the timer, they note what the urge did. The page makes no promise about what happens after fifteen minutes; that is a new choice. Watch for a client who uses the timer as a countdown to use.', '[{"id": "f0", "type": "textarea", "label": "The moment the urge arrived, and what set it off:"}, {"id": "f1", "type": "textarea", "label": "Where the urge sits in my body, what temperature it is, and how it moves:"}, {"id": "f2", "type": "textarea", "label": "What my mind is promising if I give in, word for word:"}, {"id": "f3", "type": "textarea", "label": "One small valued thing I will do with my hands for the fifteen minutes:"}, {"id": "f4", "type": "textarea", "label": "At the timer: what the urge did, out of ten at the start and now:"}, {"id": "f5", "type": "textarea", "label": "The next choice, made fresh, and who I will tell about this quarter hour:"}]'::jsonb, array['addiction', 'urges', 'willingness']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-current-emotion-behind-the-urge-card', 'Mindfulness of Current Emotion Behind the Urge Card', 'dbt'::resource_kind, 'A card for finding the emotion underneath an urge to use and observing that emotion as a wave rather than acting on the urge.', 'Use it to help a client notice what the urge is covering and ride that emotion without the substance.', array['Adults', 'Teens']::text[], '10 minutes, in the moment', 'Urges are often the first thing a client feels and the last thing that is actually happening; underneath is usually an emotion the urge promises to erase. The card asks the client to pause at the urge, name the emotion under it (lonely, ashamed, bored, scared), find it in the body, and observe it as a wave with a beginning, a peak and an end, without pushing it away or holding on. The urge is noted and set aside; the emotion gets the attention. Watch for a client who names the emotion as craving; craving is the urge, and the question is what the craving is for.', '[{"id": "f0", "type": "textarea", "label": "The urge, rated out of ten, and the moment it arrived:"}, {"id": "f1", "type": "textarea", "label": "The emotion underneath it, named in one word:"}, {"id": "f2", "type": "textarea", "label": "Where that emotion lives in my body right now:"}, {"id": "f3", "type": "textarea", "label": "Observing it as a wave: where is it, rising, peaking or falling:"}, {"id": "f4", "type": "textarea", "label": "What I did instead of pushing it away or feeding it:"}, {"id": "f5", "type": "textarea", "label": "Ten minutes later: the emotion, the urge, and what I know about tonight that I did not know before:"}]'::jsonb, array['addiction', 'urges', 'mindfulness']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('home-supply-and-guest-drinks-agreement-for-partners', 'Home Supply and Guest Drinks Agreement for Partners', 'couples'::resource_kind, 'An agreement about what substances are kept in the house, what is served to guests, and how either partner reopens the deal.', 'Use it to help a couple settle a practical question that usually becomes an argument about trust and control.', array['Couples']::text[], '30 minutes', 'Whether alcohol or other substances live in the house is a decision couples rarely make on purpose; it happens by default and gets fought about at the worst time. The agreement asks the partner working on their substance use what they want in the house and what they can be around, the other partner what they want for themselves and for guests, and both to settle what is kept, where, and what is served when friends come. It also sets how either partner reopens the deal without it becoming an accusation. Watch for the agreement being used as surveillance; the terms are the couple''s, not a test.', '[{"id": "f0", "type": "textarea", "label": "Partner working on substance use: what I want in the house, and what I can be around right now:"}, {"id": "f1", "type": "textarea", "label": "Other partner: what I want for myself, and what I want to offer guests:"}, {"id": "f2", "type": "textarea", "label": "What we agree is kept in the house, and where:"}, {"id": "f3", "type": "textarea", "label": "What we serve when friends come, and who handles it:"}, {"id": "f4", "type": "textarea", "label": "How either of us reopens this agreement without it sounding like an accusation:"}, {"id": "f5", "type": "textarea", "label": "The first date we will check in on how this is working:"}]'::jsonb, array['addiction', 'couples', 'boundaries']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('customer-facing-shift-anger-decompression-sheet', 'Customer-Facing Shift Anger Decompression Sheet', 'worksheet'::resource_kind, 'A sheet for the service worker who leaves a shift full of swallowed anger, with a decompression routine before they get home.', 'Use it to help a client who absorbs rudeness all day release it on purpose rather than on the first person they see at home.', array['Adults']::text[], '10 minutes after each shift', 'Clients in service, retail, call centers and healthcare swallow anger for hours and then let it out on the commute or the kitchen. The sheet is filled in the car or on the walk: the three worst moments of the shift in one line each, what the client wanted to say and could not, where the anger sits in the body now, one physical release before the door (a walk around the block, a loud song, a shake-out), and the sentence that tells the people at home what kind of shift it was. Watch for a client who skips the sheet on the worst days; those are the ones it is for.', '[{"id": "f0", "type": "textarea", "label": "The three worst moments of the shift, one line each:"}, {"id": "f1", "type": "textarea", "label": "What I wanted to say and could not, written here where it is safe:"}, {"id": "f2", "type": "textarea", "label": "Where the anger sits in my body right now, and how hot it is out of ten:"}, {"id": "f3", "type": "textarea", "label": "One physical release before I walk in the door:"}, {"id": "f4", "type": "textarea", "label": "The sentence I will say to the people at home about what kind of shift it was:"}, {"id": "f5", "type": "textarea", "label": "After a week: which days I used this, and what the evenings were like:"}]'::jsonb, array['anger management', 'work', 'regulation']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('kids-sports-sideline-thought-record', 'Kids'' Sports Sideline Thought Record', 'cbt'::resource_kind, 'A thought record for the parent who finds themselves furious at the referee, the coach or another parent on the sideline.', 'Use it to help a client catch the thoughts that turn a children''s game into a fight and choose who their child sees on the sideline.', array['Adults']::text[], '15 minutes after the game', 'Sideline anger embarrasses clients because they know how it looks, and knowing does not stop it. The record captures the moment (the call, the substitution, the other parent''s comment), the hot thought (my kid is being cheated, that coach has it in for us, they think I am a pushover), the feeling, the evidence, and the alternative view. The last row asks what the client wants their child to see on the sideline and how that version would stand and speak. Watch for a client who defends the anger as advocacy; ask what the child looked like when they turned around.', '[{"id": "f0", "type": "textarea", "label": "The moment on the sideline: the call, the comment, or the substitution:"}, {"id": "f1", "type": "textarea", "label": "My hot thought in that moment, word for word:"}, {"id": "f2", "type": "textarea", "label": "What I did with my body and voice, and what my child saw:"}, {"id": "f3", "type": "textarea", "label": "Evidence for and against the hot thought:"}, {"id": "f4", "type": "textarea", "label": "Another way to read the same moment:"}, {"id": "f5", "type": "textarea", "label": "Who I want my child to see on the sideline, and how that parent would stand and speak:"}]'::jsonb, array['anger management', 'parenting', 'thought record']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('winning-the-argument-or-keeping-the-evening-page', 'Winning the Argument or Keeping the Evening Page', 'act'::resource_kind, 'A choice point page for the moment an argument could be won, asking whether winning serves the evening the client actually wanted.', 'Use it to help a client who always wins the argument notice what winning costs and choose the evening instead.', array['Adults', 'Teens']::text[], '15 minutes', 'Some clients are very good at arguments and keep winning them at the cost of every evening. The page catches the choice point: the moment the winning line is available. It asks what winning gets them (being right, being safe, not being pushed around), what it has cost in the last month, what the evening they actually wanted looked like, and what they could say at the choice point that keeps the evening without surrendering the point. Not every argument should be dropped; the page is about noticing there is a choice. Watch for a client who hears this as being told to lose.', '[{"id": "f0", "type": "textarea", "label": "The last argument I won, and what the evening was like afterward:"}, {"id": "f1", "type": "textarea", "label": "What winning gets me, honestly: being right, being safe, something else:"}, {"id": "f2", "type": "textarea", "label": "What winning has cost me this month, in evenings and in closeness:"}, {"id": "f3", "type": "textarea", "label": "The evening I actually wanted, described in a line:"}, {"id": "f4", "type": "textarea", "label": "What I can say at the choice point that keeps the evening and does not surrender me:"}, {"id": "f5", "type": "textarea", "label": "The next time I feel the winning line arrive: what I will notice first:"}]'::jsonb, array['anger management', 'values', 'conflict']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('accepts-push-away-after-a-heated-email-card', 'ACCEPTS Push Away After a Heated Email Card', 'dbt'::resource_kind, 'An ACCEPTS card for the hour after reading an email that makes the client furious, using distraction skills to delay the reply.', 'Use it to give a client a specific set of distraction skills for the hour between the infuriating email and a reply they will not regret.', array['Adults']::text[], 'One hour, as needed', 'The furious reply is written in the first ten minutes and regretted for weeks. The card puts ACCEPTS between the email and the reply: an activity that takes the hands, a contribution to someone else, a comparison to a worse email survived, a different emotion from a song or a clip, pushing the email away by closing the tab and listing it for later, a thought that occupies (count backward, name the states), and a sensation (cold water, a brisk walk). The reply is drafted after the hour, read once, and sent the next morning. Watch for a client who pushes it away for a week; the list has a date.', '[{"id": "f0", "type": "textarea", "label": "The email, and the first line I wanted to fire back:"}, {"id": "f1", "type": "textarea", "label": "Activities: the one thing that will take my hands for twenty minutes:"}, {"id": "f2", "type": "textarea", "label": "Contributing: one small thing I can do for someone else in this hour:"}, {"id": "f3", "type": "textarea", "label": "Pushing away: the tab is closed; the date and time I will come back to it:"}, {"id": "f4", "type": "textarea", "label": "Thoughts and sensations: what I will count or name, and what I will feel on my skin:"}, {"id": "f5", "type": "textarea", "label": "The reply, drafted after the hour and sent the next morning: what changed between the first line and the sent version:"}]'::jsonb, array['anger management', 'distress tolerance', 'work']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('button-pusher-spotting-bingo-game', 'Button Pusher Spotting Bingo Game', 'game'::resource_kind, 'A bingo game in which the squares are common anger triggers and players mark the ones that pushed their buttons this week, then compare.', 'Use it to get a group naming their anger triggers out loud and noticing that many of them are shared.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Each player gets a bingo card of common button pushers (being interrupted, being told to calm down, a slow driver, a sigh, being ignored in a text, being overruled, being told what to do, a mess someone else made) and a few blank squares for their own. Round one: mark every square that got you this week. Round two: the caller reads triggers at random, and the first to five in a row wins the round but must describe their earliest warning sign for one of the five. Debrief: which squares did most of the room mark, and which were yours alone. Watch for players mocking each other''s squares.', '[{"id": "f0", "type": "textarea", "label": "The squares you marked this week, and the two that pushed hardest:"}, {"id": "f1", "type": "textarea", "label": "The triggers you wrote in your blank squares:"}, {"id": "f2", "type": "textarea", "label": "A square most of the room marked, and what that tells you:"}, {"id": "f3", "type": "textarea", "label": "A square only you marked, and where you think it comes from:"}, {"id": "f4", "type": "textarea", "label": "Your earliest warning sign for your biggest square:"}, {"id": "f5", "type": "textarea", "label": "One square you will watch for this week before it gets to full heat:"}]'::jsonb, array['anger management', 'group', 'triggers']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('just-right-handwriting-rewrite-count-sheet', 'Just Right Handwriting Rewrite Count Sheet', 'worksheet'::resource_kind, 'A count sheet for the letters, words and pages a client rewrites until they look right, with a daily cap and a note on the urge.', 'Use it to help a client who rewrites for the feeling of rightness see the count, cap it, and practice leaving a page imperfect.', array['Adults', 'Teens']::text[], '5 minutes a day for two weeks', 'Rewriting for a just-right feeling is slow, private, and often missed because it looks like neatness. The sheet counts it: how many times a word or line was rewritten each day, how long the writing took, and the urge level when a page was left as it was. From day four the client sets a cap (one rewrite per page, then none) and records what the urge did when the cap held. Watch for the client who moves the rewriting to typing and deleting; the count includes that too.', '[{"id": "f0", "type": "textarea", "label": "Each day: how many rewrites, and how long the writing took:"}, {"id": "f1", "type": "textarea", "label": "The urge, out of ten, when I left a page with a letter that was not right:"}, {"id": "f2", "type": "textarea", "label": "My cap from day four, and how often it held:"}, {"id": "f3", "type": "textarea", "label": "What the urge did in the ten minutes after I left the page alone:"}, {"id": "f4", "type": "textarea", "label": "One page this week I left imperfect on purpose, and what happened when someone else saw it:"}, {"id": "f5", "type": "textarea", "label": "What I did with the time the rewriting used to take:"}]'::jsonb, array['OCD', 'self-monitoring', 'rituals']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('sitting-on-the-hotel-bedspread-prediction-sheet', 'Sitting on the Hotel Bedspread Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for contamination fears in a hotel room, testing what they expect after sitting on the bedspread or using the remote.', 'Use it to help a client turn a hotel stay into a set of specific predictions they can test and record.', array['Adults']::text[], '10 minutes before the stay, 10 minutes after', 'Hotel rooms gather every contamination fear in one place: the bedspread, the remote, the glasses, the carpet. The sheet asks for the specific prediction (I will feel contaminated all night, I will get sick within three days, I will not stop thinking about it), its confidence rating, and the step the client will take (sit on the bedspread for five minutes, use the remote without a tissue). Afterward the client records what happened over three days. The step is chosen by the client. Watch for safety behaviors creeping in, like a shower right afterward, and record them as part of the test.', '[{"id": "f0", "type": "textarea", "label": "The hotel room step I will take, chosen by me:"}, {"id": "f1", "type": "textarea", "label": "My prediction about what will happen, and how sure I am out of a hundred:"}, {"id": "f2", "type": "textarea", "label": "What I predict the urge to wash or check will do, and for how long:"}, {"id": "f3", "type": "textarea", "label": "What I actually did, including any washing or checking afterward, honestly:"}, {"id": "f4", "type": "textarea", "label": "Three days later: what happened, and what did not:"}, {"id": "f5", "type": "textarea", "label": "My confidence in the prediction now, and the next room item I will test:"}]'::jsonb, array['OCD', 'predictions', 'exposure']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('values-walk-past-the-unchecked-door-page', 'Values Walk Past the Unchecked Door Page', 'act'::resource_kind, 'A values page for leaving the house without the last check, framing the walk past the door as a step toward something the client wants.', 'Use it to help a client leave the lock unchecked once by connecting the uncertainty to the morning they would rather have.', array['Adults', 'Teens']::text[], '15 minutes, then one morning', 'Checking the door is about certainty; the page is about what the client would do with the minutes and the mental space the checking takes. It asks what the morning would look like if the door got one lock and one walk away, what value that morning serves (being on time for a child, a calm commute, trusting their own hands), what the doubt will say on the sidewalk, and what willing looks like there: keep walking, hands in pockets, the doubt invited along. One morning is the assignment. Watch for a client who checks by photo instead; the page is about carrying the doubt, not replacing the check.', '[{"id": "f0", "type": "textarea", "label": "What the morning would look like with one lock, one walk away, and no return:"}, {"id": "f1", "type": "textarea", "label": "The value that morning serves, in my own words:"}, {"id": "f2", "type": "textarea", "label": "What the doubt will say on the sidewalk, word for word:"}, {"id": "f3", "type": "textarea", "label": "What willing looks like there: my hands, my pace, the doubt along for the walk:"}, {"id": "f4", "type": "textarea", "label": "The one morning this week I will do it:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what the doubt did by the time I reached the corner, and by lunch:"}]'::jsonb, array['OCD', 'values', 'willingness']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-of-the-thought-i-did-not-choose-card', 'Radical Acceptance of the Thought I Did Not Choose Card', 'dbt'::resource_kind, 'A radical acceptance card for an intrusive thought, accepting that the thought arrived and is here without accepting that it means anything.', 'Use it to help a client stop fighting the arrival of an intrusive thought and turn the mind toward the day instead.', array['Adults', 'Teens']::text[], '5 minutes, in the moment', 'Fighting an intrusive thought for arriving is a second problem laid on top of the first. The card separates what is accepted (the thought showed up, uninvited, and is here right now) from what is not being asked (that it is true, that it says anything about the client, that it should be liked). The client states the fact of the thought''s arrival, notices the body''s refusal, relaxes it with willing hands or a breath, and turns the mind back to the task, as often as the thought returns. Watch for a client who tries to accept the thought''s content; the acceptance is of its arrival only.', '[{"id": "f0", "type": "textarea", "label": "The thought arrived. The fact of it, stated in one line without the content:"}, {"id": "f1", "type": "textarea", "label": "What my body does when it refuses: jaw, hands, breath:"}, {"id": "f2", "type": "textarea", "label": "What I accept (the thought showed up and is here) and what I do not accept (that it is true or means anything):"}, {"id": "f3", "type": "textarea", "label": "Willing hands or one slow breath, then: what I turn my mind back to:"}, {"id": "f4", "type": "textarea", "label": "How many times I turned the mind back today, and what that was like by evening:"}]'::jsonb, array['OCD', 'radical acceptance', 'intrusive thoughts']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('crooked-tower-build-and-walk-away-game', 'Crooked Tower Build and Walk Away Game', 'game'::resource_kind, 'A group game of building block towers that must be left crooked, uneven and unfinished when the timer sounds, with no fixing allowed.', 'Use it to let a group practice the discomfort of leaving something not right and compare how long the discomfort lasts.', array['Teens', 'Groups']::text[], '25 minutes', 'Each player or pair gets a pile of blocks and three minutes to build a tower that is deliberately crooked, uneven or unfinished in one way the player chooses. When the timer sounds, everyone steps back and walks once around the room; touching a tower after the timer costs a point. Round two: players rate their urge to fix out of ten at the timer and again after the walk. Round three: everyone swaps towers and must leave someone else''s not-right tower alone. Debrief: what did the urge do over two minutes, and whose tower was hardest to leave. Watch for a player who fixes by nudging on the walk.', '[{"id": "f0", "type": "textarea", "label": "What you left not right about your tower, and your urge to fix it at the timer, out of ten:"}, {"id": "f1", "type": "textarea", "label": "Your urge after the walk around the room:"}, {"id": "f2", "type": "textarea", "label": "Which was harder: leaving your own tower or someone else''s:"}, {"id": "f3", "type": "textarea", "label": "What the urge did over the two minutes, in your own words:"}, {"id": "f4", "type": "textarea", "label": "Something in your week you could leave crooked for two minutes as practice:"}]'::jsonb, array['OCD', 'game', 'group']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('first-surge-in-a-new-place-debrief-sheet', 'First Surge in a New Place Debrief Sheet', 'worksheet'::resource_kind, 'A debrief sheet for the first panic surge in a place the client had felt safe, catching the new avoidance before it sets.', 'Use it to help a client process a surge in a new location so the place does not join the list of places they no longer go.', array['Adults', 'Teens']::text[], '15 minutes within a day of the surge', 'A surge in a new place is how the map of avoided locations grows: one episode in a bookstore and the bookstore is gone. The sheet is filled within a day: where it happened, what the body did, how long the peak lasted by the clock, what the client did and what they wanted to do, what the mind now says about the place, and the plan to return within a week while the memory is still just a memory. Watch for a client who treats the return as optional; the sheet is most useful when the return date is set before the session ends.', '[{"id": "f0", "type": "textarea", "label": "Where it happened, and what I was doing in the minute before:"}, {"id": "f1", "type": "textarea", "label": "What my body did, and how long the peak lasted by the clock:"}, {"id": "f2", "type": "textarea", "label": "What I did during the surge, and what I wanted to do instead:"}, {"id": "f3", "type": "textarea", "label": "What my mind now says about the place, word for word:"}, {"id": "f4", "type": "textarea", "label": "The date within the next week I will go back, and who knows about it:"}, {"id": "f5", "type": "textarea", "label": "After the return visit: what the body did, and what the place is to me now:"}]'::jsonb, array['panic attacks', 'avoidance', 'self-monitoring']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('if-i-do-not-sit-down-i-will-collapse-prediction-sheet', 'If I Do Not Sit Down I Will Collapse Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the belief that standing through a panic surge will end in collapse, with a standing experiment to test it.', 'Use it to help a client test the collapse prediction by staying on their feet through a surge and recording what the legs actually did.', array['Adults', 'Teens']::text[], '20 minutes to plan, then one surge', 'The sitting-down safety behavior is nearly universal and rarely questioned: the client sits, the surge passes, and sitting gets the credit. The sheet writes the prediction (my legs will give out, I will fall, people will see me on the floor), rates it, and plans a standing experiment: during the next surge, stay standing with a wall nearby, feet apart, and note what the legs do minute by minute. The client reviews it afterward with the clinician. Watch for a history of fainting at the sight of blood or needles, a different mechanism; this sheet is for the panic surge only.', '[{"id": "f0", "type": "textarea", "label": "The prediction, word for word, and my confidence out of a hundred:"}, {"id": "f1", "type": "textarea", "label": "What I usually do with my body during a surge, and what I think it prevents:"}, {"id": "f2", "type": "textarea", "label": "The standing experiment: where, with what wall nearby, and how I will stand:"}, {"id": "f3", "type": "textarea", "label": "Minute by minute during the surge: what my legs actually did:"}, {"id": "f4", "type": "textarea", "label": "How long the peak lasted standing, compared with my memory of sitting:"}, {"id": "f5", "type": "textarea", "label": "My confidence in the prediction now, and where I will stand next time:"}]'::jsonb, array['panic attacks', 'behavioral experiment', 'predictions']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('unhooking-from-what-if-it-happens-here-page', 'Unhooking From What If It Happens Here Page', 'act'::resource_kind, 'A defusion page for the what-if thought that arrives at every new venue, practicing unhooking from it rather than answering it.', 'Use it to help a client notice the what-if-here question as a hook and stay in the venue without resolving it.', array['Adults', 'Teens']::text[], '15 minutes, then in the moment', 'The what-if-it-happens-here thought is a hook: the client bites, starts scanning exits and heart rate, and the surge gets its foothold. The page teaches the unhooking move: notice the thought, name it (there is the what-if), thank the mind, and put attention on something in the room with the eyes and ears for thirty seconds. The thought is not answered, because answering it is biting. The client practices at three venues this week and records whether they stayed. Watch for a client who unhooks by reassuring themselves it will not happen; that is a different hook.', '[{"id": "f0", "type": "textarea", "label": "The what-if thought, as it arrives at a new venue, word for word:"}, {"id": "f1", "type": "textarea", "label": "What biting the hook looks like for me: scanning, checking, planning an exit:"}, {"id": "f2", "type": "textarea", "label": "The unhooking move I will use: name it, thank the mind, then eyes and ears on the room for thirty seconds:"}, {"id": "f3", "type": "textarea", "label": "Venue one this week: did I bite or unhook, and did I stay:"}, {"id": "f4", "type": "textarea", "label": "Venues two and three: the same:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the thought''s grip over the week:"}]'::jsonb, array['panic attacks', 'defusion', 'willingness']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('paired-muscle-relaxation-before-the-train-ride-card', 'Paired Muscle Relaxation Before the Train Ride Card', 'dbt'::resource_kind, 'A paired muscle relaxation card for the minutes before boarding a train, bus or subway, pairing tension and release with the out-breath.', 'Use it to give a client a body-based skill to use on the platform so they board with lower baseline tension.', array['Adults']::text[], '5 minutes on the platform', 'Clients who dread public transit arrive on the platform already tight, and the surge has a head start. Paired muscle relaxation gives the wait a job: tense a muscle group on the in-breath, say relax and release on the out-breath, working from the hands up to the face, all of it doable standing with a bag over the shoulder. The card lists the groups, the pairing word, and a check of tension out of ten before and after. On board, the client repeats the hands and shoulders only. Watch for a client who holds the breath while tensing; the breath keeps moving.', '[{"id": "f0", "type": "textarea", "label": "Tension out of ten as I arrive on the platform:"}, {"id": "f1", "type": "textarea", "label": "Hands and forearms: tense on the in-breath, relax on the out-breath. What I noticed:"}, {"id": "f2", "type": "textarea", "label": "Shoulders and neck: the same:"}, {"id": "f3", "type": "textarea", "label": "Jaw and face: the same:"}, {"id": "f4", "type": "textarea", "label": "Tension out of ten as the train arrives:"}, {"id": "f5", "type": "textarea", "label": "On board: the groups I repeat, and how the ride went compared with my usual:"}]'::jsonb, array['panic attacks', 'distress tolerance', 'regulation']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('sensation-station-rotation-game', 'Sensation Station Rotation Game', 'game'::resource_kind, 'A group game rotating through stations that produce ordinary body sensations, with players rating and naming each one before moving on.', 'Use it to let a group produce and sit with the sensations panic uses, in a setting that is playful and clearly safe.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes, clinician present', 'Set up four or five stations: spin in a chair for thirty seconds, run in place for a minute, breathe through a straw for thirty seconds, stare at a bright wall then a dim corner, hold the breath for twenty seconds. Players rotate in pairs, do the station, rate the sensation out of ten, name it in plain words, and wait until it has dropped by half before moving on. The clinician runs it and sits out anyone with a medical reason. Debrief: which station felt most like a surge, how long each took to fade, and what that says about sensations in the wild. Watch for competition; the timer is fixed.', '[{"id": "f0", "type": "textarea", "label": "The station that felt most like a surge, and its rating out of ten:"}, {"id": "f1", "type": "textarea", "label": "How long it took each sensation to drop by half:"}, {"id": "f2", "type": "textarea", "label": "The plain-words name you gave your strongest sensation:"}, {"id": "f3", "type": "textarea", "label": "What your partner noticed about you that you did not:"}, {"id": "f4", "type": "textarea", "label": "What the stations tell you about the sensations when they arrive uninvited:"}]'::jsonb, array['panic attacks', 'group', 'body awareness']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('allowance-and-chores-agreement-draft-sheet', 'Allowance and Chores Agreement Draft Sheet', 'worksheet'::resource_kind, 'A drafting sheet for a family agreement on chores and allowance, separating money from help and deciding what is expected and what is paid.', 'Use it to help a parent set up a chore and allowance system they can hold to, with the child''s input on the terms.', array['Adults']::text[], '30 minutes for the parent, then a family meeting', 'Chore and allowance fights often come from a system that was never agreed, only announced. The sheet has the parent decide what is expected of everyone unpaid (because you live here), what is optional and paid, how much and how often, what happens when a chore is skipped (no lecture, just the agreed consequence), and which parts the child gets a say in at the family meeting. The parent also writes what they will do when they want to pay for a good mood or withhold for a bad one. Watch for a system with twenty rules; three expected chores and two paid ones is plenty to start.', '[{"id": "f0", "type": "textarea", "label": "Expected and unpaid, because you live here: the two or three chores for each child:"}, {"id": "f1", "type": "textarea", "label": "Optional and paid: the chores, the rate, and the payday:"}, {"id": "f2", "type": "textarea", "label": "What happens when an expected chore is skipped, stated as the consequence without a lecture:"}, {"id": "f3", "type": "textarea", "label": "The parts the children get a say in at the family meeting:"}, {"id": "f4", "type": "textarea", "label": "What I will do when I am tempted to pay for a good mood or withhold for a bad one:"}, {"id": "f5", "type": "textarea", "label": "After a month: what held, what did not, and what we will change together:"}]'::jsonb, array['parenting', 'routines', 'family']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('a-bad-report-card-means-i-failed-as-a-parent-sheet', 'A Bad Report Card Means I Failed as a Parent Sheet', 'cbt'::resource_kind, 'A thought check for the parent who reads a child''s grades as a verdict on their own parenting, with the other factors laid out.', 'Use it to help a parent separate the report card from their worth and respond to the child from a steadier place.', array['Adults']::text[], '15 minutes before talking to the child', 'A bad report card lands on the parent first, and if it lands as a verdict the conversation with the child becomes about the parent''s shame. The sheet records the grade, the thought (I failed them, everyone will see I did not do enough), the feeling, the list of factors that shape a grade (teacher, class, friendships, sleep, the subject, the term, the child''s own choices), what share of those the parent actually controls, and a plan for the conversation that is about the child''s next step. Watch for a parent who swings to blaming the child entirely; the share row keeps both honest.', '[{"id": "f0", "type": "textarea", "label": "The grade, and the sentence it said about me as a parent:"}, {"id": "f1", "type": "textarea", "label": "The feeling, and how strong it was out of ten:"}, {"id": "f2", "type": "textarea", "label": "Everything that shapes a grade, listed without ranking:"}, {"id": "f3", "type": "textarea", "label": "The share of that list I actually control, in an honest fraction:"}, {"id": "f4", "type": "textarea", "label": "What I want the conversation with my child to be about, in one line:"}, {"id": "f5", "type": "textarea", "label": "My opening sentence to my child, and when I will say it:"}]'::jsonb, array['parenting', 'thinking traps', 'self-talk']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('letting-my-child-fail-the-science-project-willingness-page', 'Letting My Child Fail the Science Project Willingness Page', 'act'::resource_kind, 'A willingness page for the parent who rescues every project, asking what it would take to let a child''s work be the child''s work.', 'Use it to help a parent tolerate watching a child struggle or fall short on something low-stakes, in service of the child''s own growth.', array['Adults']::text[], '20 minutes, then one project', 'Many parents cannot watch a child''s volcano stay unpainted, and the rescue teaches the child that their work is not good enough on its own. The page names the value behind the rescue (I want them to do well, I do not want them embarrassed), the value behind stepping back (I want them to own their work), what the parent will feel watching, and what willing looks like: hands in pockets, questions not fixes, letting the grade be the grade. The project is chosen for low stakes. Watch for a parent who steps back and then sabotages with commentary; silence is part of the practice.', '[{"id": "f0", "type": "textarea", "label": "The last project I rescued, and what I did:"}, {"id": "f1", "type": "textarea", "label": "The value behind the rescue, named kindly:"}, {"id": "f2", "type": "textarea", "label": "The value behind stepping back, in my own words:"}, {"id": "f3", "type": "textarea", "label": "What I will feel watching them struggle or fall short, and where I will feel it:"}, {"id": "f4", "type": "textarea", "label": "What willing looks like: my hands, my mouth, what I do with the urge to fix:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what the project looked like, what my child said about it, and what I learned:"}]'::jsonb, array['parenting', 'willingness', 'values']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('wise-mind-before-taking-the-phone-away-card', 'Wise Mind Before Taking the Phone Away Card', 'dbt'::resource_kind, 'A wise mind card for the moment a parent reaches for a teen''s phone as a consequence, pausing between the fury and the fold.', 'Use it to help a parent decide about a consequence from wise mind rather than from the heat of the moment or the fear of the fallout.', array['Adults']::text[], '5 minutes, in the moment', 'Taking the phone is the modern go-to consequence, and it is usually decided in emotion mind (you are done, give it here) or abandoned in reasonable mind (it is not worth the war). The card gives the parent a pause: what emotion mind wants, what reasonable mind argues, a breath, and the wise mind question of what consequence they can follow through on calmly and would still stand by tomorrow. It also writes the sentence that delivers it without the speech. Watch for a parent whose wise mind always lands on no consequence; the card is for finding one they can keep.', '[{"id": "f0", "type": "textarea", "label": "What my teen did, in one factual line:"}, {"id": "f1", "type": "textarea", "label": "What emotion mind wants to do with the phone right now:"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind argues, including the fallout it predicts:"}, {"id": "f3", "type": "textarea", "label": "After one slow breath: the consequence I can follow through on calmly and would stand by tomorrow:"}, {"id": "f4", "type": "textarea", "label": "The sentence that delivers it, with no speech attached:"}, {"id": "f5", "type": "textarea", "label": "What I actually did, and how it held over the next two days:"}]'::jsonb, array['parenting', 'wise mind', 'de-escalation']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('family-team-flag-design-craft', 'Family Team Flag Design Craft', 'kids'::resource_kind, 'A family flag designed and painted together, with a symbol from each member and a motto, hung where the family gathers.', 'Use it to give a family a shared object that says who they are together, made by every member including the parent.', array['Children']::text[], '45 minutes', 'The family draws a flag on a pillowcase, a large sheet of paper or a piece of felt. Each member adds one symbol for something they bring to the family (a joke, a hug, pancakes, music) and the group votes on a motto of five words or fewer. The parent''s part is to contribute a symbol too, to let the child''s symbol stand even if it is a dinosaur, and to hang the flag where meals or arguments happen. At a hard moment later, anyone can point at it. Watch for a parent who takes over the design; the flag belongs to everyone who drew on it.', '[{"id": "f0", "type": "textarea", "label": "Your symbol: what you bring to this family, and what you drew for it:"}, {"id": "f1", "type": "textarea", "label": "Grown-up: your symbol, and what it stands for:"}, {"id": "f2", "type": "textarea", "label": "The motto the family voted on, five words or fewer:"}, {"id": "f3", "type": "textarea", "label": "Where the flag will hang, and why that spot:"}, {"id": "f4", "type": "textarea", "label": "Draw the whole flag here as a small copy:"}, {"id": "f5", "type": "textarea", "label": "What someone could do when they point at the flag during a hard moment:"}]'::jsonb, array['parenting', 'children', 'craft']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('due-date-passed-waiting-days-plan-sheet', 'Due Date Passed Waiting Days Plan Sheet', 'worksheet'::resource_kind, 'A plan for the days after a due date comes and goes, with a daily shape, a script for the check-in texts, and what to do with the dread.', 'Use it to help an expectant client get through the overdue days with a structure instead of a countdown.', array['Adults']::text[], '15 minutes, then daily until the birth', 'The days past a due date are a strange suspended time: every text asks if anything has happened, every twinge is examined, and the plan the client made has nothing in it for this. The sheet gives each waiting day a shape (one outing, one rest, one thing finished), a reply to the check-in texts that the client can paste, a list of what the dread says and what the care team actually said at the last visit, and who to call for the medical questions so they are not answered by searching online. Watch for a client who stops leaving the house in case; the one outing matters.', '[{"id": "f0", "type": "textarea", "label": "The shape of a waiting day: one outing, one rest, one thing to finish:"}, {"id": "f1", "type": "textarea", "label": "The reply I will paste when someone texts to ask if anything has happened:"}, {"id": "f2", "type": "textarea", "label": "What the dread says, and what the care team actually said at the last visit:"}, {"id": "f3", "type": "textarea", "label": "Who I call with a medical question, and the number, so I am not searching online at midnight:"}, {"id": "f4", "type": "textarea", "label": "What my partner or support person does on these days that helps, said plainly:"}, {"id": "f5", "type": "textarea", "label": "Each waiting day: what I did, and one good thing in it:"}]'::jsonb, array['perinatal and postpartum', 'planning', 'uncertainty']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('second-baby-will-break-me-prediction-sheet', 'Second Baby Will Break Me Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the expectant parent certain a second child will undo them, weighing the first time against what is different now.', 'Use it to help a client separate a hard memory of the first newborn months from a prediction about the next.', array['Adults']::text[], '20 minutes', 'Parents who had a hard first postpartum stretch often approach the second with a prediction built entirely from the first. The sheet writes the prediction, rates it, and compares then and now: what made the first time hard, which of those factors are present now, which are different (a known pediatrician, a partner who knows what to look for, a toddler who sleeps, help arranged in advance), and what the client knows now that they did not. It ends with a plan that answers the hardest factor from the first time. Watch for a client who dismisses every difference as not enough; list them anyway.', '[{"id": "f0", "type": "textarea", "label": "The prediction, word for word, and my confidence out of a hundred:"}, {"id": "f1", "type": "textarea", "label": "What made the first time hard, listed as factors rather than as a verdict on me:"}, {"id": "f2", "type": "textarea", "label": "Which of those factors are present now, and which are different:"}, {"id": "f3", "type": "textarea", "label": "What I know now that I did not know then:"}, {"id": "f4", "type": "textarea", "label": "The hardest factor from the first time, and the plan that answers it this time:"}, {"id": "f5", "type": "textarea", "label": "My confidence now, and the one person who will know about this sheet:"}]'::jsonb, array['perinatal and postpartum', 'predictions', 'planning']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('the-parent-scorecard-the-mind-keeps-defusion-page', 'The Parent Scorecard the Mind Keeps Defusion Page', 'act'::resource_kind, 'A defusion page for the running scorecard a new parent''s mind keeps, noticing the scoring as a mind habit rather than a true ranking.', 'Use it to help a new parent see the mind''s constant grading of their parenting and set the scorecard down for an hour at a time.', array['Adults']::text[], '15 minutes, then daily', 'New parents describe a scorecard that never stops: points off for the formula, for the screen, for the tears, for the nap missed. The page asks the client to write the scorecard as their mind actually keeps it, to notice who the mind imagines is reading it, to name it when it starts (there is the scorecard), and to choose one hour a day when the scorecard is set on the counter and the parent simply does the next thing with the baby. The hour is recorded. Watch for a client who tries to win the scorecard instead of setting it down; a perfect score is still the scorecard.', '[{"id": "f0", "type": "textarea", "label": "The scorecard as my mind keeps it: what gains points, what loses them:"}, {"id": "f1", "type": "textarea", "label": "Who my mind imagines is reading the scorecard:"}, {"id": "f2", "type": "textarea", "label": "What I will say when I notice it start: there is the scorecard, or my own words:"}, {"id": "f3", "type": "textarea", "label": "The hour each day the scorecard goes on the counter, and what I will do with the baby in it:"}, {"id": "f4", "type": "textarea", "label": "Day by day: the hour, and what I noticed without the scoring:"}, {"id": "f5", "type": "textarea", "label": "What the baby seemed to notice, if anything:"}]'::jsonb, array['perinatal and postpartum', 'defusion', 'self-criticism']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('check-the-facts-on-the-pediatrician-s-raised-eyebrow-card', 'Check the Facts on the Pediatrician''s Raised Eyebrow Card', 'dbt'::resource_kind, 'A check the facts card for the moment a care provider''s expression or question is read as judgment of the new parent.', 'Use it to help a new parent separate what the pediatrician said from what their fear says the eyebrow meant.', array['Adults']::text[], '10 minutes after the appointment', 'A clinician''s neutral question (how is feeding going) or a glance at the chart becomes, in the parking lot, proof that the parent is failing. The card asks for the exact words said, the interpretation the parent added, the emotion and its intensity, whether the emotion fits the facts of what was said rather than the facts of what was imagined, and the one question the parent can ask at the next visit to find out. Watch for a client who refuses to ask because asking would confirm they are a bad parent; write the question anyway and practice it once.', '[{"id": "f0", "type": "textarea", "label": "What the provider actually said, word for word as best I remember:"}, {"id": "f1", "type": "textarea", "label": "What I added to it in the parking lot:"}, {"id": "f2", "type": "textarea", "label": "The emotion, and its intensity out of ten:"}, {"id": "f3", "type": "textarea", "label": "Does the emotion fit the facts of what was said, or the facts of what I imagined:"}, {"id": "f4", "type": "textarea", "label": "The one question I can ask at the next visit to find out what they meant:"}, {"id": "f5", "type": "textarea", "label": "What I will tell my partner or support person about the visit, facts first:"}]'::jsonb, array['perinatal and postpartum', 'check the facts', 'emotion regulation']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('worry-gap-about-the-baby-talk-sheet-for-new-parents', 'Worry Gap About the Baby Talk Sheet for New Parents', 'couples'::resource_kind, 'A talk sheet for the couple in which one partner checks the baby constantly and the other seems unbothered, naming what each does with it.', 'Use it to help two new parents understand the gap in their worry levels without one being the anxious one and the other the careless one.', array['Couples']::text[], '30 minutes', 'In most couples one partner carries the baby worry visibly and the other appears not to, and each reads the other''s level as a judgment. The sheet has each partner describe their worry (how often they check, what they look for, what they do with it at three in the morning), what they believe the other''s level means, and what they actually want from each other: not to be told to relax, not to be told to care more. They agree on who checks when and on a sentence for the moment the gap shows. Watch for a partner who hides their worry to seem calm; ask what they do when alone with the monitor.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my worry about the baby, honestly: how often I check, what I look for, what I do with it at night:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the same, including the worry I hide to seem calm:"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I have assumed my partner''s level means about them:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I have assumed about mine:"}, {"id": "f4", "type": "textarea", "label": "What each of us actually wants from the other on a worried night, said plainly:"}, {"id": "f5", "type": "textarea", "label": "Who checks when, and the sentence for the moment the gap shows:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'worry']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('opinions-i-hold-without-permission-inventory-sheet', 'Opinions I Hold Without Permission Inventory Sheet', 'worksheet'::resource_kind, 'An inventory of opinions the client holds, whether they have said them out loud, and whose approval they waited for first.', 'Use it to help a client who defers on everything find the opinions they already have and practice saying one.', array['Adults', 'Teens']::text[], '20 minutes, then one week', 'Clients with low self-regard often believe they have no opinions, when what they have is a habit of checking the room before admitting one. The inventory lists topics big and small (the movie, the restaurant, the political question, the way a project is going), what the client actually thinks about each, whether they have said it, and whose reaction they waited for before deciding what they thought. The week''s practice is one stated opinion a day, small ones first. Watch for a client who states opinions as questions; write the sentence as a sentence.', '[{"id": "f0", "type": "textarea", "label": "Topics from this week where I had a view: the movie, the plan, the meeting, the meal:"}, {"id": "f1", "type": "textarea", "label": "What I actually think about each, written as a sentence not a question:"}, {"id": "f2", "type": "textarea", "label": "Which ones I said out loud, and which I kept until I saw what others thought:"}, {"id": "f3", "type": "textarea", "label": "Whose reaction I usually wait for before I know what I think:"}, {"id": "f4", "type": "textarea", "label": "This week''s practice: one opinion a day, stated as a sentence, starting with the smallest:"}, {"id": "f5", "type": "textarea", "label": "After a week: which ones I said, what happened, and what I noticed about my voice:"}]'::jsonb, array['self-esteem', 'assertiveness', 'self-monitoring']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('they-only-hired-me-because-they-were-desperate-record', 'They Only Hired Me Because They Were Desperate Record', 'cbt'::resource_kind, 'A thought record for the client who explains away every success as luck, charity or someone else''s low standards.', 'Use it to help a client examine the discounting story they tell about a success and build a fairer account of how it happened.', array['Adults']::text[], '20 minutes', 'The desperate-employer story is one version of a common move: a success arrives and the mind finds a reason it does not count. The record takes the specific success, the discount (they had no one else, they felt sorry for me, the bar was low), the belief rating, the evidence (the process, the competition, what the decision maker said, what the client did to get there), an alternative account, and what the client would say about a friend hired in the same way. Watch for a client who agrees the evidence is strong and keeps the belief anyway; note the gap as the thing to work on.', '[{"id": "f0", "type": "textarea", "label": "The success, stated plainly, and when it happened:"}, {"id": "f1", "type": "textarea", "label": "The discount my mind applied to it, word for word, and how much I believe it out of a hundred:"}, {"id": "f2", "type": "textarea", "label": "What the process actually involved, and who else was in it:"}, {"id": "f3", "type": "textarea", "label": "What the decision maker actually said about why:"}, {"id": "f4", "type": "textarea", "label": "What I did, over months or years, that put me in that room:"}, {"id": "f5", "type": "textarea", "label": "What I would say about a friend who got the same job and told me this story:"}, {"id": "f6", "type": "textarea", "label": "My belief in the discount now, out of a hundred:"}]'::jsonb, array['self-esteem', 'thinking traps', 'thought record']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('dropping-the-impress-everyone-rule-willingness-page', 'Dropping the Impress Everyone Rule Willingness Page', 'act'::resource_kind, 'A willingness page for the rule that the client must impress every person they meet, and what one unimpressed afternoon would make room for.', 'Use it to help a client notice the cost of the impress-everyone rule and try one setting where they let someone be unimpressed.', array['Adults', 'Teens']::text[], '20 minutes, then one afternoon', 'The rule is rarely stated but runs everything: every conversation is an audition. The page writes the rule in the client''s words, lists what it costs (the exhaustion, the performance, never being known), names what the client would do with the energy, and picks one low-stakes setting this week where they will be ordinary on purpose: say something plain, not add the impressive detail, let a silence sit. Willing means feeling the pull to perform and not following it. Watch for a client who performs being ordinary; the test is whether they feel the pull.', '[{"id": "f0", "type": "textarea", "label": "The rule, in my own words: who I must impress, and what happens if I do not:"}, {"id": "f1", "type": "textarea", "label": "What the rule costs me in a typical week:"}, {"id": "f2", "type": "textarea", "label": "What I would do with the energy if I were not auditioning:"}, {"id": "f3", "type": "textarea", "label": "One low-stakes setting this week where I will be ordinary on purpose, and what that looks like:"}, {"id": "f4", "type": "textarea", "label": "What willing feels like there: the pull to perform, noticed and not followed:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what the other person did, and what it was like to be unimpressive for an afternoon:"}]'::jsonb, array['self-esteem', 'willingness', 'values']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('fast-skill-returning-an-item-without-apologizing-card', 'FAST Skill Returning an Item Without Apologizing Card', 'dbt'::resource_kind, 'A FAST card for returning a purchase or sending back a wrong order, keeping self-respect without the apology the client usually opens with.', 'Use it to give a client a small daily place to practice self-respect effectiveness in a transaction they are entitled to.', array['Adults', 'Teens']::text[], '10 minutes to prepare, then the return', 'Returning something is an ordinary right that clients with low self-regard turn into an apology. FAST gives it a shape: fair to themselves and the clerk, no apologies for having a receipt, stick to the value of being treated as a customer, truthful about why without inventing an excuse. The card writes the opening sentence without sorry in it, the one fact the client will give, and what they will do if the clerk sighs. The return is done this week. Watch for the apology creeping into the body: the shrug, the half laugh; name them before the trip.', '[{"id": "f0", "type": "textarea", "label": "The item or order, and the return I am entitled to:"}, {"id": "f1", "type": "textarea", "label": "My opening sentence, with no sorry in it:"}, {"id": "f2", "type": "textarea", "label": "The one truthful reason I will give, without an invented excuse:"}, {"id": "f3", "type": "textarea", "label": "What I will do with my body and voice if the clerk sighs:"}, {"id": "f4", "type": "textarea", "label": "Fair: what is fair to me and fair to the clerk here:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what I said, what happened, and where the apology tried to sneak in:"}]'::jsonb, array['self-esteem', 'FAST', 'interpersonal effectiveness']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('strength-detective-clue-reveal-game', 'Strength Detective Clue Reveal Game', 'game'::resource_kind, 'A group game in which clues about a player''s strengths are revealed one at a time and the group guesses who is being described.', 'Use it to let a group hear their strengths described by others in concrete clues, without having to claim them first.', array['Teens', 'Groups']::text[], '30 minutes', 'Before the game, each player writes three clues about another player''s strengths on index cards, drawn from the group''s shared time, concrete and about behavior (always notices when someone is quiet, explained the rules twice without sighing). The leader reads one clue at a time and the group guesses who it is; the fewer clues needed, the more visible the strength. The described player then says whether they knew that about themselves. Debrief: which clue surprised its owner, and which strengths everyone saw but the person who has them. Watch for clues about appearance; send them back.', '[{"id": "f0", "type": "textarea", "label": "The clues written about you, as best you remember them:"}, {"id": "f1", "type": "textarea", "label": "How many clues it took the group to guess you, and what that tells you:"}, {"id": "f2", "type": "textarea", "label": "The clue that surprised you most:"}, {"id": "f3", "type": "textarea", "label": "A clue you wrote about someone else that they did not know about themselves:"}, {"id": "f4", "type": "textarea", "label": "One strength named here that you will let yourself believe this week:"}]'::jsonb, array['self-esteem', 'strengths', 'group']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('wedding-reception-table-small-talk-plan-sheet', 'Wedding Reception Table Small Talk Plan Sheet', 'worksheet'::resource_kind, 'A plan for the reception table of strangers: three openers, two topics, an exit to the bar or the dance floor, and a debrief.', 'Use it to help a client who dreads assigned seating walk in with a plan for the first twenty minutes at the table.', array['Adults']::text[], '20 minutes before the event', 'The reception table is a small-talk endurance test: hours with strangers, no exit, and a client who believes everyone else finds it easy. The sheet prepares three openers that need no cleverness (how do you know the couple, did you travel far), two topics the client can speak about for a minute, a graceful exit to the bar, the restroom or the dance floor, and the prediction to test. The debrief the next day records who the client actually talked to. Watch for a client who plans to sit silently and hope; the sheet asks them to pick the one person at the table they will speak to first.', '[{"id": "f0", "type": "textarea", "label": "Three openers that need no cleverness, written out in full:"}, {"id": "f1", "type": "textarea", "label": "Two topics I can talk about for a minute if asked:"}, {"id": "f2", "type": "textarea", "label": "The one person at the table I will speak to first, and how I will decide who that is:"}, {"id": "f3", "type": "textarea", "label": "My exit to the bar, the restroom or the dance floor, and the sentence that goes with it:"}, {"id": "f4", "type": "textarea", "label": "My prediction about how the table will go, and my confidence out of a hundred:"}, {"id": "f5", "type": "textarea", "label": "The next day: who I actually talked to, and how the prediction held up:"}]'::jsonb, array['social anxiety', 'planning', 'social skills']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('they-only-invited-me-out-of-politeness-thought-record', 'They Only Invited Me Out of Politeness Thought Record', 'cbt'::resource_kind, 'A thought record for the invitation the client reads as an obligation on the host''s part rather than a wish to see them.', 'Use it to help a client examine the politeness story and decide about an invitation on evidence rather than assumption.', array['Adults', 'Teens']::text[], '15 minutes', 'The politeness story lets a client decline every invitation while keeping the belief that they are unwanted intact. The record takes the invitation, the thought (they had to ask me, they will be relieved if I say no), the feeling, the evidence (how it was phrased, whether there was follow-up, what this person has done before), the alternative, and a test: go, and notice what the host does when the client arrives. Watch for a client who goes, is greeted warmly, and decides the host was being polite in person too; the record needs a line for what evidence would count.', '[{"id": "f0", "type": "textarea", "label": "The invitation, exactly as it was phrased, and how it arrived:"}, {"id": "f1", "type": "textarea", "label": "My thought about why they asked, word for word:"}, {"id": "f2", "type": "textarea", "label": "The feeling, and how strong it was out of ten:"}, {"id": "f3", "type": "textarea", "label": "Evidence for and against the politeness story, including what this person has done before:"}, {"id": "f4", "type": "textarea", "label": "What evidence would count as them actually wanting me there:"}, {"id": "f5", "type": "textarea", "label": "If I go: what the host did when I arrived, written the same night:"}]'::jsonb, array['social anxiety', 'thinking traps', 'thought record']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('carrying-the-blush-into-the-meeting-page', 'Carrying the Blush Into the Meeting Page', 'act'::resource_kind, 'A willingness page for walking into the meeting while blushing, taking the red face along instead of waiting for it to pass outside.', 'Use it to help a client who hides until the blush fades enter the room with it and speak anyway.', array['Adults', 'Teens']::text[], '15 minutes, then one meeting', 'Clients who blush often wait outside the door until it fades, and the waiting is what costs them the meeting. The page does not aim to stop the blush. It asks what the blush has cost this month, what the client values in the room (being heard, being part of the team), what willing looks like at the door (walk in, sit down, say the first sentence with the red face), and what the mind will say about everyone noticing. One meeting is the practice. Watch for a client who walks in and then hides behind a laptop; the first sentence is part of the step.', '[{"id": "f0", "type": "textarea", "label": "What waiting for the blush to fade has cost me this month:"}, {"id": "f1", "type": "textarea", "label": "What I value in that room, in my own words:"}, {"id": "f2", "type": "textarea", "label": "What willing looks like at the door: walk in, sit, first sentence, red face and all:"}, {"id": "f3", "type": "textarea", "label": "What my mind will say about who is noticing, word for word:"}, {"id": "f4", "type": "textarea", "label": "The meeting this week I will carry the blush into:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what I said, what anyone did about my face, and what it was like to be in the room:"}]'::jsonb, array['social anxiety', 'willingness', 'acceptance']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('self-soothe-after-an-awkward-exchange-card', 'Self-Soothe After an Awkward Exchange Card', 'dbt'::resource_kind, 'A self-soothe card for the minutes after a conversation goes awkwardly, giving the body comfort before the mind starts the replay.', 'Use it to help a client treat an awkward moment as a thing to recover from with kindness rather than a thing to prosecute.', array['Adults', 'Teens']::text[], '10 minutes, in the moment', 'After an awkward exchange, clients go straight to the replay, and the replay is where the moment becomes a verdict. The card inserts ten minutes of self-soothing first: a warm drink, a hand on the chest, a favorite track, a step outside, a scent. The replay is postponed, not banned, and when it comes it is done once with the clinician''s questions (what actually happened, what did the other person do). The card lists the five senses and the client''s choice for each, and where the kit lives on a workday. Watch for a client who soothes and then replays for an hour; the once rule matters.', '[{"id": "f0", "type": "textarea", "label": "The awkward exchange, in two factual lines, written after the ten minutes not before:"}, {"id": "f1", "type": "textarea", "label": "Touch: what I will do with my hands in the first minute:"}, {"id": "f2", "type": "textarea", "label": "Taste or smell: what I will reach for:"}, {"id": "f3", "type": "textarea", "label": "Sound or sight: the track or the view:"}, {"id": "f4", "type": "textarea", "label": "Where this kit lives on a workday, so I can reach it within five minutes:"}, {"id": "f5", "type": "textarea", "label": "After the ten minutes, the replay done once with two questions: what actually happened, and what did they do:"}]'::jsonb, array['social anxiety', 'self-soothing', 'distress tolerance']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('pass-the-spotlight-thirty-second-talk-game', 'Pass the Spotlight Thirty Second Talk Game', 'game'::resource_kind, 'A group game where each player holds the spotlight for exactly thirty seconds on an easy topic and passes it, then rates how long it felt.', 'Use it to let a socially anxious group practice being briefly the center of attention in a structured, fast-moving round.', array['Teens', 'Groups']::text[], '25 minutes', 'A flashlight or a paper spotlight is the token. The holder talks for thirty seconds on a card topic (the best sandwich, a chore you secretly like, a place you want to see) while the group listens without interrupting; at the timer, the holder passes to anyone. Round two: the holder rates how long the thirty seconds felt before the timer is revealed. Round three: listeners each say one thing they remember from a holder''s turn. Debrief: how long did it feel versus how long it was, and what did the listeners actually remember. Watch for players who pass immediately; the timer runs for everyone.', '[{"id": "f0", "type": "textarea", "label": "How long your thirty seconds felt, and how long it actually was:"}, {"id": "f1", "type": "textarea", "label": "What you remember from two other players'' turns:"}, {"id": "f2", "type": "textarea", "label": "What the listeners remembered from yours, and whether it matched what you worried they noticed:"}, {"id": "f3", "type": "textarea", "label": "The topic that was easiest, and the one you would dread:"}, {"id": "f4", "type": "textarea", "label": "One place this week you could hold the spotlight for thirty seconds on purpose:"}]'::jsonb, array['social anxiety', 'group', 'exposure']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('condolence-messages-reply-pacing-sheet', 'Condolence Messages Reply Pacing Sheet', 'worksheet'::resource_kind, 'A pacing sheet for the pile of condolence cards, texts and voicemails, deciding who gets a reply, when, and what the short version says.', 'Use it to lift the obligation of answering every kind message at once off a grieving client and give them a pace they can keep.', array['Adults']::text[], '15 minutes to set up, then a few minutes a day', 'After a death the kindness arrives all at once and becomes a debt. The sheet sorts the messages into three piles (reply soon, reply when I can, a reply is not needed), writes one short sentence the client can send to most people, names the two or three people who get a longer note, and sets a daily cap of replies so the pile is worked rather than dreaded. It also gives permission in writing to leave some unanswered. Watch for a client who treats every unanswered message as a failure of gratitude; the not-needed pile is as real as the others.', '[{"id": "f0", "type": "textarea", "label": "The messages I have received, sorted into reply soon, reply when I can, and no reply needed:"}, {"id": "f1", "type": "textarea", "label": "The one short sentence I can send to most people:"}, {"id": "f2", "type": "textarea", "label": "The two or three people who get a longer note, and when I will write it:"}, {"id": "f3", "type": "textarea", "label": "My daily cap on replies, so the pile is worked and not dreaded:"}, {"id": "f4", "type": "textarea", "label": "The permission I am giving myself, in writing, about the ones I leave:"}, {"id": "f5", "type": "textarea", "label": "A week in: how the pile looks, and how it feels to open the phone:"}]'::jsonb, array['grief and loss', 'pacing', 'support']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('crying-in-public-means-i-am-falling-apart-thought-record', 'Crying in Public Means I Am Falling Apart Thought Record', 'cbt'::resource_kind, 'A thought record for the grieving client who weeps in the grocery store or the office and concludes they are losing their grip.', 'Use it to help a client separate a wave of grief in public from the verdict they attach to it about their stability.', array['Adults', 'Teens']::text[], '15 minutes', 'Grief ambushes in public places, and the client''s shame about it adds a second wound. The record takes the moment (the song in the store, the question at work), the thought (I am falling apart, people think I cannot cope, this should not still be happening), the feeling, the evidence against the verdict (what the client did in the next hour, how they got home, what the week otherwise held), and a kinder, truer description of a wave of grief in aisle six. Watch for a client whose evidence row is empty because they left the store; leaving the store counts as handling it.', '[{"id": "f0", "type": "textarea", "label": "Where it happened, and what set it off:"}, {"id": "f1", "type": "textarea", "label": "The verdict I handed myself about it, word for word:"}, {"id": "f2", "type": "textarea", "label": "What I did in the next hour, including getting home:"}, {"id": "f3", "type": "textarea", "label": "What the rest of the week otherwise held: the work done, the meals made, the calls returned:"}, {"id": "f4", "type": "textarea", "label": "What the people who saw me actually did, if anything:"}, {"id": "f5", "type": "textarea", "label": "A kinder and truer sentence about a wave of grief in a public place:"}]'::jsonb, array['grief and loss', 'thinking traps', 'self-talk']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('grief-as-a-houseguest-who-stays-page', 'Grief as a Houseguest Who Stays Page', 'act'::resource_kind, 'A metaphor page in which grief is a houseguest who moved in uninvited, and the client learns to live in the house with them, not evict them.', 'Use it to help a client stop waiting for grief to leave and find a way to live alongside it while doing what still matters.', array['Adults', 'Teens']::text[], '25 minutes', 'Clients often arrive expecting grief to leave by a certain date and feel they have failed when it does not. The page gives grief a room: it moved in uninvited, it is loud some days and quiet others, it rearranges the furniture without asking, and evicting it has not worked. The questions ask what living with this houseguest looks like (which rooms they share, when the client needs the kitchen alone), what the client still does with the guest present, and what the guest brings that is not only pain. Watch for a client who hears this as grief being fine; the guest is unwelcome and still here.', '[{"id": "f0", "type": "textarea", "label": "What the houseguest is like on a loud day, and on a quiet one:"}, {"id": "f1", "type": "textarea", "label": "What I have tried in order to evict them, and how it went:"}, {"id": "f2", "type": "textarea", "label": "Which rooms we share, and when I need a room to myself:"}, {"id": "f3", "type": "textarea", "label": "What I still do in the house while the guest is present:"}, {"id": "f4", "type": "textarea", "label": "What the guest sometimes brings that is not only pain, if anything yet:"}, {"id": "f5", "type": "textarea", "label": "One thing I will do this week in the house, with the guest, that matters to me:"}]'::jsonb, array['grief and loss', 'acceptance', 'metaphor']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-the-empty-side-of-the-bed-card', 'Mindfulness of the Empty Side of the Bed Card', 'dbt'::resource_kind, 'A mindfulness card for the bedtime moment a bereaved client faces the empty side of the bed, observing and describing without the story.', 'Use it to give a widowed or bereaved client a way to meet the hardest minute of the night with attention rather than avoidance or collapse.', array['Adults']::text[], '5 minutes at bedtime', 'The empty side of the bed is the moment many bereaved clients dread most, and they fill it with the television, the couch, or the replay. The card gives it a mindful shape: observe the room (the light, the cool sheet, the sounds), describe it in plain words, notice the wave that arrives and name it, let it be present without the story that comes with it, and then choose the next small action (the lamp off, a hand on the pillow, a sentence said to the empty side if the client wants to). Watch for a client who uses the card to force sleep; sleep is not the task, meeting the minute is.', '[{"id": "f0", "type": "textarea", "label": "Observe: three things in the room right now, in plain words:"}, {"id": "f1", "type": "textarea", "label": "The wave as it arrives: where it is in my body, and its name:"}, {"id": "f2", "type": "textarea", "label": "The story that wants to come with it, noticed and set beside me for now:"}, {"id": "f3", "type": "textarea", "label": "One sentence to the empty side, if I want to say one:"}, {"id": "f4", "type": "textarea", "label": "The next small action: the lamp, the pillow, the breath:"}, {"id": "f5", "type": "textarea", "label": "In the morning: what the minute was like, compared with the nights I avoid it:"}]'::jsonb, array['grief and loss', 'mindfulness', 'sleep']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('goodbye-letter-paper-boat-float-craft', 'Goodbye Letter Paper Boat Float Craft', 'kids'::resource_kind, 'A paper boat a child decorates and floats in a tub or stream, carrying a drawn or written message to the person or pet who died.', 'Use it to give a grieving child a concrete way to send a message and watch it go, with a parent beside them.', array['Children']::text[], '30 minutes', 'The child folds a paper boat (the parent helps with the folds) and decorates the sail or the hull with a drawing or a few words for the person or pet who died: a thank you, a thing they want them to know, a goodbye. Then the boat is floated in the bathtub, a puddle or a stream, and the two watch it go. The parent''s part is to make their own boat with their own message, to say that missing someone is allowed to last a long time, and to answer the questions that come up plainly. The boat can be made again at anniversaries. Watch for a child who will not let it go; it can be dried and kept.', '[{"id": "f0", "type": "textarea", "label": "Decorate your boat. What did you draw or write for the person or pet who died:"}, {"id": "f1", "type": "textarea", "label": "Grown-up: what did you put on your boat:"}, {"id": "f2", "type": "textarea", "label": "Where did you float it, and what did it do:"}, {"id": "f3", "type": "textarea", "label": "What did it feel like to watch it go:"}, {"id": "f4", "type": "textarea", "label": "A question you have about where they are or what happened. Grown-up: answer it plainly:"}, {"id": "f5", "type": "textarea", "label": "Would you like to make another boat on a special day? Which day:"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('adult-child-and-parent-phone-call-frequency-sheet', 'Adult Child and Parent Phone Call Frequency Sheet', 'worksheet'::resource_kind, 'A sheet for settling how often an adult child and a parent talk, what the calls are for, and how a missed call is handled on both sides.', 'Use it to help a client turn a standing guilt or resentment about family calls into an explicit, livable rhythm.', array['Adults']::text[], '20 minutes, then a conversation with the parent', 'The weekly call with a parent carries more freight than its length: too few and the client is a bad child, too many and they are suffocating. The sheet asks what the client''s current rhythm is, what the parent seems to want and how they signal it, what the client can genuinely offer (a Sunday call, a daily text, a monthly visit), what the calls are for from each side, and the sentence for proposing the rhythm to the parent. It also writes how a missed call is handled without an apology tour. Watch for a client who proposes a rhythm they cannot keep in order to avoid the conversation.', '[{"id": "f0", "type": "textarea", "label": "Our current rhythm: how often we talk, who calls, and how long:"}, {"id": "f1", "type": "textarea", "label": "What my parent seems to want, and how they let me know:"}, {"id": "f2", "type": "textarea", "label": "What I can genuinely offer and keep up for a year:"}, {"id": "f3", "type": "textarea", "label": "What the calls are for, from my side and from theirs:"}, {"id": "f4", "type": "textarea", "label": "The sentence I will use to propose the rhythm, without defending it:"}, {"id": "f5", "type": "textarea", "label": "How a missed call is handled on both sides, without an apology tour:"}]'::jsonb, array['relationship issues', 'family', 'boundaries']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('my-partner-s-bad-mood-is-about-me-thought-record', 'My Partner''s Bad Mood Is About Me Thought Record', 'cbt'::resource_kind, 'A thought record for the client who treats a partner''s low or irritable mood as a message about themselves and starts fixing or bracing.', 'Use it to help a client separate a partner''s mood from a verdict on the relationship and respond without over-reading.', array['Adults']::text[], '15 minutes', 'Clients who grew up reading a parent''s moods for safety keep reading their partner''s the same way: a quiet evening becomes evidence. The record takes the mood observed (the short answers, the sigh), the thought (they are angry with me, I did something, they are pulling away), the feeling and the behavior it drove (asking what is wrong three times, going quiet too), the evidence, the alternative explanations (work, sleep, their own mind), and one plain question the client can ask once. Watch for a client who asks the question as an accusation; write it as curiosity.', '[{"id": "f0", "type": "textarea", "label": "What I observed in my partner tonight, in facts only:"}, {"id": "f1", "type": "textarea", "label": "My thought about what it meant about me, word for word:"}, {"id": "f2", "type": "textarea", "label": "The feeling, and what it made me do:"}, {"id": "f3", "type": "textarea", "label": "Evidence that the mood is about me, and evidence it is not:"}, {"id": "f4", "type": "textarea", "label": "Three other reasons a person has a quiet evening:"}, {"id": "f5", "type": "textarea", "label": "The one plain question I can ask once, written as curiosity not accusation:"}]'::jsonb, array['relationship issues', 'thinking traps', 'thought record']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('values-when-a-friend-lets-me-down-again-page', 'Values When a Friend Lets Me Down Again Page', 'act'::resource_kind, 'A values page for the recurring letdown in a friendship, asking who the client wants to be in response rather than what the friend deserves.', 'Use it to help a client choose a response to a repeated letdown from their values instead of from the ledger.', array['Adults', 'Teens']::text[], '20 minutes', 'When a friend lets a client down again, the mind goes to the ledger (how many times, what I have done for them) and the ledger never decides anything. The page asks what happened this time in one line, what the ledger says, what the client values in friendship (honesty, loyalty, ease), what responding from that value would look like here (saying something plainly, scaling back without a speech, letting it go once more on purpose), and the cost of each. Ending the friendship is a legitimate option on the page. Watch for a client who confuses values with being nice; honesty is a value too.', '[{"id": "f0", "type": "textarea", "label": "What happened this time, in one line without the history:"}, {"id": "f1", "type": "textarea", "label": "What the ledger says, and how long I have been keeping it:"}, {"id": "f2", "type": "textarea", "label": "What I value in a friendship, in three words or less:"}, {"id": "f3", "type": "textarea", "label": "Three responses from that value, from saying something to stepping back to letting it go on purpose:"}, {"id": "f4", "type": "textarea", "label": "The honest cost of each of the three:"}, {"id": "f5", "type": "textarea", "label": "The response I choose this time, and the sentence that goes with it, if one is needed:"}]'::jsonb, array['relationship issues', 'values', 'friendship']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('give-skill-when-a-friend-shares-bad-news-card', 'GIVE Skill When a Friend Shares Bad News Card', 'dbt'::resource_kind, 'A GIVE card for the moment a friend shares bad news and the client freezes, fixes or changes the subject, with a skillful response written.', 'Use it to help a client stay present for a friend''s hard news with a relationship-effectiveness skill instead of a reflex.', array['Adults', 'Teens']::text[], '10 minutes, then the next time it happens', 'Clients who care deeply often respond badly to bad news: a joke, a solution, a story about themselves. GIVE gives them a different reflex: be gentle (no fixing yet, no judgment), act interested (eye contact, a question, the phone down), validate (that sounds hard, of course you feel that), use an easy manner (a little warmth, no drama). The card writes the client''s usual reflex, the GIVE response for a recent piece of news they handled badly, and the first sentence they will use next time. Watch for a client who validates with a formula; the words should be theirs.', '[{"id": "f0", "type": "textarea", "label": "The last time a friend shared bad news, and what I did in the first minute:"}, {"id": "f1", "type": "textarea", "label": "Gentle: what I will not do (fix, joke, judge) in the first minute:"}, {"id": "f2", "type": "textarea", "label": "Interested: what my body and my first question will look like:"}, {"id": "f3", "type": "textarea", "label": "Validate: the sentence in my own words that says their reaction makes sense:"}, {"id": "f4", "type": "textarea", "label": "Easy manner: what warmth looks like from me without drama:"}, {"id": "f5", "type": "textarea", "label": "Next time: the first sentence I will use, written out:"}]'::jsonb, array['relationship issues', 'GIVE', 'interpersonal effectiveness']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('weeknight-dinner-decision-fatigue-pact-for-partners', 'Weeknight Dinner Decision Fatigue Pact for Partners', 'couples'::resource_kind, 'A pact for the nightly what-do-you-want-to-eat standoff: decision days, a default menu, and a rule for the night neither can choose.', 'Use it to remove a small daily friction from a couple''s evenings and make visible who has been carrying the deciding.', array['Couples']::text[], '20 minutes', 'The dinner question is asked every night, answered by neither, and resented by both. The pact assigns decision days (Monday is yours, Tuesday is mine), writes a default menu of five meals that need no discussion, sets the rule for the night neither can choose (the default list, a coin, takeout from a set place), and names who has been carrying most of the deciding until now. Each partner also says what a good weeknight dinner is for them, since it may not be the food. Watch for a partner who agrees to a decision day and then asks the other what they want anyway.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what a good weeknight dinner is for me, which may not be about the food:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the same:"}, {"id": "f2", "type": "textarea", "label": "Who has been carrying most of the deciding until now, acknowledged in a line:"}, {"id": "f3", "type": "textarea", "label": "Our decision days, and what the decider gets to decide without a vote:"}, {"id": "f4", "type": "textarea", "label": "The default menu of five meals, and the rule for the night neither of us can choose:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: how many standoffs, and what we each noticed about the evenings:"}]'::jsonb, array['relationship issues', 'couples', 'fairness']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('deciding-on-a-sleepover-safety-sheet-for-teens', 'Deciding on a Sleepover Safety Sheet for Teens', 'worksheet'::resource_kind, 'A sheet for a teen deciding about a sleepover or overnight trip, with the questions that make it feel safe enough and a plan if it does not.', 'Use it to help a teen client who has experienced abuse make an overnight decision from a plan rather than from avoidance or pressure.', array['Teens']::text[], '20 minutes in session', 'Overnights are a decision point many teens with a history of abuse refuse outright or accept under pressure, and both leave them without a plan. The sheet asks what would need to be true for this overnight to feel safe enough (who is there, where they sleep, whether a door locks, whether a ride home is available at any hour), the code word to text a trusted adult to be picked up with no questions, what to do if someone makes them uncomfortable, and a decision that can be no. It does not ask about the history. Watch for a teen deciding yes to seem normal; name the exit plan as a strength.', '[{"id": "f0", "type": "textarea", "label": "What would need to be true for this overnight to feel safe enough: who, where, locks, a ride:"}, {"id": "f1", "type": "textarea", "label": "The trusted adult I can text, and the code word that means pick me up now, no questions:"}, {"id": "f2", "type": "textarea", "label": "What I will do if someone makes me uncomfortable, including the room I can go to:"}, {"id": "f3", "type": "textarea", "label": "Where I will sleep, and what I will bring that helps me settle:"}, {"id": "f4", "type": "textarea", "label": "My decision, which is allowed to be no, and how I will say it:"}, {"id": "f5", "type": "textarea", "label": "If I go: how it went, and what I would change next time:"}]'::jsonb, array['sexual abuse', 'safety', 'planning']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('enjoying-closeness-means-i-am-damaged-gentle-check-sheet', 'Enjoying Closeness Means I Am Damaged Gentle Check Sheet', 'cbt'::resource_kind, 'A gentle thought check for the survivor who feels that pleasure or comfort in closeness now is itself a sign of being damaged.', 'Use it to help a client question the belief that enjoying closeness is wrong, in a paced way that stays with the present.', array['Adults']::text[], '20 minutes in session', 'Many survivors describe guilt or alarm when closeness feels good now, and read the enjoyment as proof that something in them is wrong. The sheet stays in the present: the moment of closeness (a hug, a hand held, a kiss with a chosen partner), the thought that followed, the feeling, what the client knows about choice and safety in that moment, and a gentler sentence. It does not ask what happened in the past. Complete it in session, and stop if the client moves toward the history. Watch for a client who answers every row with the past; bring them back to the hug on Tuesday.', '[{"id": "f0", "type": "textarea", "label": "The recent moment of closeness, with someone I chose, in one line:"}, {"id": "f1", "type": "textarea", "label": "The thought that followed, word for word:"}, {"id": "f2", "type": "textarea", "label": "The feeling, and where it sat in my body:"}, {"id": "f3", "type": "textarea", "label": "What was true about choice and safety in that moment:"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend who told me they felt guilty for enjoying a hug:"}, {"id": "f5", "type": "textarea", "label": "A gentler sentence about Tuesday''s moment, even if I only half believe it yet:"}]'::jsonb, array['sexual abuse', 'stabilizing', 'self-talk']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('hope-as-a-pilot-light-not-a-bonfire-page', 'Hope as a Pilot Light Not a Bonfire Page', 'act'::resource_kind, 'A values page for the survivor who feels no hope and concludes none is left, finding the small steady flame that got them to the session.', 'Use it to help a client locate a small, durable form of hope in their own behavior rather than in a feeling they do not have.', array['Adults', 'Teens']::text[], '20 minutes in session', 'Clients in the stabilizing stage often say they have no hope, and they mean they feel none. The page separates the bonfire (the feeling of hope, which comes and goes) from the pilot light (the small flame that keeps a person showing up: they came today, they set an alarm, they fed the cat). It asks what the pilot light has been doing this month, what it is in service of, and what it would need to stay lit: not more feeling, just a little fuel. Nothing here asks about the history. Watch for a client who dismisses the pilot light as nothing; the appointment is evidence.', '[{"id": "f0", "type": "textarea", "label": "Evidence my pilot light is on: things I did this month that a person with no hope at all would not do:"}, {"id": "f1", "type": "textarea", "label": "What those small things are in service of, in my own words:"}, {"id": "f2", "type": "textarea", "label": "The difference between the bonfire I am waiting for and the pilot light that is already lit:"}, {"id": "f3", "type": "textarea", "label": "What my pilot light needs to stay lit this week: not more feeling, just a little fuel:"}, {"id": "f4", "type": "textarea", "label": "One sentence to myself for the days the bonfire does not come:"}]'::jsonb, array['sexual abuse', 'values', 'stabilizing']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('observe-the-flinch-without-the-apology-card', 'Observe the Flinch Without the Apology Card', 'dbt'::resource_kind, 'A mindfulness card for the startle at an unexpected touch, observing it and letting it pass without the apology the client usually adds.', 'Use it to help a survivor meet a flinch as a body event rather than a failing that needs a sorry.', array['Adults', 'Teens']::text[], '5 minutes, in the moment', 'Survivors often flinch at a tap on the shoulder and immediately apologize, which teaches them that their body''s protection is an offense. The card observes the flinch (the jump, the breath caught, the heat), describes it in plain words, names it as the body doing its job, lets the apology urge be noticed and not acted on, and chooses what to say instead, if anything (you startled me, or nothing at all). The card does not ask what the flinch is tied to. Watch for a client who replaces the apology with an explanation; the body does not owe one.', '[{"id": "f0", "type": "textarea", "label": "The flinch, described in plain body words: what jumped, what caught, what heated:"}, {"id": "f1", "type": "textarea", "label": "The apology urge, noticed: what it wanted to say:"}, {"id": "f2", "type": "textarea", "label": "What I say instead, if anything: you startled me, or nothing:"}, {"id": "f3", "type": "textarea", "label": "The sentence I keep for myself: my body did its job:"}, {"id": "f4", "type": "textarea", "label": "How many times this week I noticed the flinch and skipped the sorry:"}]'::jsonb, array['sexual abuse', 'mindfulness', 'grounding']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('okay-and-not-okay-touch-thumbs-cards-craft', 'Okay and Not Okay Touch Thumbs Cards Craft', 'kids'::resource_kind, 'Thumbs-up and thumbs-down cards a child decorates and uses to sort everyday touches with a parent, learning to say which are okay for them.', 'Use it to give a young child words and a signal for okay and not-okay touch, with the parent practicing listening to the signal.', array['Children']::text[], '25 minutes', 'The child decorates a thumbs-up card and a thumbs-down card, then the parent names everyday touches (a high five, a hug from grandma, a tickle that lasts too long, a doctor checking ears with a parent there, someone touching a private part) and the child holds up a card. The parent accepts the child''s answer even about a relative''s hug, says private parts are what a swimsuit covers and no one touches them except for health with a parent there, and practices: I say stop and I tell a grown-up. If a child discloses during this activity, follow your mandated reporting duties and stop questioning.', '[{"id": "f0", "type": "textarea", "label": "Decorate your thumbs-up and thumbs-down cards:"}, {"id": "f1", "type": "textarea", "label": "Grown-up names a touch; you hold up a card. Which touches got thumbs-up:"}, {"id": "f2", "type": "textarea", "label": "Which touches got thumbs-down, and did your grown-up listen:"}, {"id": "f3", "type": "textarea", "label": "The sentence to practice out loud: I say stop and I tell a grown-up:"}, {"id": "f4", "type": "textarea", "label": "The grown-ups you would tell, by name:"}, {"id": "f5", "type": "textarea", "label": "Draw yourself holding up the card that means stop:"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('coping-skills-by-energy-level-menu-sheet', 'Coping Skills by Energy Level Menu Sheet', 'worksheet'::resource_kind, 'A menu sorting a client''s coping skills by how much energy they need, so the right skill is available on an empty day as well as a full one.', 'Use it to stop a client reaching for a high-energy skill on a day with no energy and concluding that nothing works.', array['Adults', 'Teens']::text[], '20 minutes', 'The run that helped last month is not available on a day the client cannot get off the couch, and the failure to run becomes proof that coping does not work. The menu sorts skills into three energy levels (no energy: lying down with a weighted blanket and a podcast; some energy: a shower and a text; full energy: the run, the cleaning, the call) and asks the client to check their actual energy before choosing. It also notes which skills they have been trying at the wrong level. Watch for a client with an empty no-energy row; that row is the one that matters most.', '[{"id": "f0", "type": "textarea", "label": "Skills that need no energy, usable lying down:"}, {"id": "f1", "type": "textarea", "label": "Skills that need some energy: standing up, one room, one message:"}, {"id": "f2", "type": "textarea", "label": "Skills that need full energy, for the days I have it:"}, {"id": "f3", "type": "textarea", "label": "How I will check my actual energy before choosing, in one honest question:"}, {"id": "f4", "type": "textarea", "label": "A skill I have been trying at the wrong energy level, and where it belongs:"}, {"id": "f5", "type": "textarea", "label": "After a week: which level I was at most days, and which skills I actually used:"}]'::jsonb, array['coping skills', 'energy', 'planning']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('using-a-skill-in-public-looks-strange-prediction-sheet', 'Using a Skill in Public Looks Strange Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the client who will not use a coping skill where anyone could see, testing what onlookers actually notice.', 'Use it to help a client test the belief that paced breathing, grounding or stepping outside is visible and judged.', array['Adults', 'Teens']::text[], '15 minutes to plan, then one public use', 'Clients often have a skill that works and refuse to use it anywhere but alone, because they predict it will look strange. The sheet writes the prediction (people will stare, someone will ask what is wrong, I will look unwell), rates it, picks a public place and a skill (paced breathing on the bus, pressing feet into the floor in a meeting, a hand on the chest in the checkout line), and records what onlookers actually did. Many skills are invisible and the sheet proves it. Watch for a client who picks the one skill that is visible; start with the invisible ones.', '[{"id": "f0", "type": "textarea", "label": "The skill I use only in private, and what I predict will happen if I use it in public:"}, {"id": "f1", "type": "textarea", "label": "My confidence in the prediction, out of a hundred:"}, {"id": "f2", "type": "textarea", "label": "The public place and the skill I will test this week:"}, {"id": "f3", "type": "textarea", "label": "What onlookers actually did, in facts:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about how visible the skill actually was:"}, {"id": "f5", "type": "textarea", "label": "My confidence now, and the next place I will use it:"}]'::jsonb, array['coping skills', 'behavioral experiment', 'predictions']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('choosing-a-skill-by-who-i-want-to-be-afterward-page', 'Choosing a Skill by Who I Want to Be Afterward Page', 'act'::resource_kind, 'A values page that picks a coping skill by asking who the client wants to be an hour from now, not just how they want to feel.', 'Use it to help a client choose between skills that feel good now and skills that leave them closer to the person they want to be.', array['Adults', 'Teens']::text[], '15 minutes, then in the moment', 'All coping skills promise relief; not all of them leave the client where they want to be. The page asks, at the hard moment, who the client wants to be an hour from now (someone who kept their word, who stayed in the room, who did not text that person), which available skills get them there, which get relief but leave them further from it, and what they chose. It is not a ban on comfort; comfort that serves the value is on the list. Watch for a client who uses the page to shame a skill they needed; the question is direction, not judgment.', '[{"id": "f0", "type": "textarea", "label": "The hard moment, and the skills I usually reach for in it:"}, {"id": "f1", "type": "textarea", "label": "Who I want to be an hour from now, in one line:"}, {"id": "f2", "type": "textarea", "label": "Which of my skills get me there, and which give relief but leave me further away:"}, {"id": "f3", "type": "textarea", "label": "A comfort skill that also serves the value, so I am not choosing between them:"}, {"id": "f4", "type": "textarea", "label": "What I chose this time, and who I was an hour later:"}, {"id": "f5", "type": "textarea", "label": "What I will remember about this next time the relief skill calls:"}]'::jsonb, array['coping skills', 'values', 'committed action']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('improve-the-moment-with-meaning-card', 'IMPROVE the Moment With Meaning Card', 'dbt'::resource_kind, 'An IMPROVE card focused on the M: finding or making meaning in a hard stretch the client cannot change, without pretending it is good.', 'Use it to help a client sit through an unavoidable hard period with one thread of meaning rather than only endurance.', array['Adults', 'Teens']::text[], '15 minutes', 'Meaning is the IMPROVE skill clients skip because it sounds like being told to find the silver lining. The card is narrower: in a hard stretch that cannot be changed (a recovery, a waiting period, a separation), what is one small purpose the client can hold inside it: learning what they can tolerate, being the kind of person who shows up for the hospital visit, keeping a plant alive through it. The card also names what the meaning does not require: liking it, being grateful for it, or growing from it. Watch for a client who constructs a grand meaning they do not believe; smaller is truer.', '[{"id": "f0", "type": "textarea", "label": "The hard stretch I am in that cannot be changed right now:"}, {"id": "f1", "type": "textarea", "label": "One small purpose I can hold inside it, in my own words:"}, {"id": "f2", "type": "textarea", "label": "What that purpose does not require of me: liking it, being grateful, growing:"}, {"id": "f3", "type": "textarea", "label": "How I will remind myself of the purpose on the worst day of the week:"}, {"id": "f4", "type": "textarea", "label": "Other IMPROVE skills I can pair with it: imagery, prayer, relaxation, one thing, vacation, encouragement:"}, {"id": "f5", "type": "textarea", "label": "A week in: whether the thread of meaning held, and what I would change:"}]'::jsonb, array['coping skills', 'distress tolerance', 'IMPROVE']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('guess-the-minutes-coping-skill-game', 'Guess the Minutes Coping Skill Game', 'game'::resource_kind, 'A group guessing game about how long each coping skill really takes, with players bidding minutes and then timing a volunteer who does it.', 'Use it to break the belief that coping skills take too long by timing them in front of the group.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'The leader names a coping skill (paced breathing to settle, a cold water face splash, writing three lines, a full-body stretch, naming five things in the room, texting one person). Players bid how many minutes it takes to do it properly; a volunteer does it while the group times it, and the closest bid wins the round. Round two: players bid on how long they usually tell themselves it would take, and compare. Debrief: which skill took far less time than people bid, and what the gap says about the phrase I do not have time. Watch for players who rush the volunteer; properly means at their pace.', '[{"id": "f0", "type": "textarea", "label": "The skill whose real time was furthest from your bid:"}, {"id": "f1", "type": "textarea", "label": "How long you usually tell yourself skills take, compared with the timer:"}, {"id": "f2", "type": "textarea", "label": "The skill you volunteered for or would volunteer for, and what it was like under the timer:"}, {"id": "f3", "type": "textarea", "label": "One skill from today that fits in a gap you actually have:"}, {"id": "f4", "type": "textarea", "label": "What the phrase I do not have time means to you now:"}]'::jsonb, array['coping skills', 'group', 'game']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('wasp-at-the-picnic-table-step-plan-sheet', 'Wasp at the Picnic Table Step Plan Sheet', 'worksheet'::resource_kind, 'A step plan for a client whose fear of wasps ends every outdoor meal, from sitting near a closed window to finishing a sandwich outside.', 'Use it to help a client build their own graded steps toward eating outdoors in wasp season, with a calm response ready for the real thing.', array['Adults', 'Teens']::text[], '20 minutes to plan, then a step a week', 'Wasp fear is sensible in small amounts and life-shrinking in large ones: the client eats inside all summer and leaves the barbecue. The sheet builds steps the client orders themselves (a video of a wasp, a picnic table with no food, a drink outside, a sandwich outside, staying seated while a wasp circles once), with the prediction and the actual outcome for each. It also writes the calm response to a real wasp (still hands, a slow lean back, let it leave) so flapping does not become the plan. Watch for a client who skips to the top step after a good week; the order is theirs, the pace steady.', '[{"id": "f0", "type": "textarea", "label": "My steps, in my order, from easiest to hardest:"}, {"id": "f1", "type": "textarea", "label": "The step I will take this week, and my prediction for it:"}, {"id": "f2", "type": "textarea", "label": "My calm response to a real wasp: hands, body, breath:"}, {"id": "f3", "type": "textarea", "label": "What actually happened on this week''s step:"}, {"id": "f4", "type": "textarea", "label": "What I will do if a wasp lands on the table: the plan written out so I do not have to decide in the moment:"}, {"id": "f5", "type": "textarea", "label": "After four steps: what I can do outside now that I could not a month ago:"}]'::jsonb, array['phobias', 'exposure', 'hierarchy']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('choking-when-swallowing-pills-prediction-sheet', 'Choking When Swallowing Pills Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the fear of choking on pills or food, with graded swallowing steps and a record of what the throat actually did.', 'Use it to help a client with a choking fear replace the catastrophic prediction with recorded results from their own practice.', array['Adults', 'Teens']::text[], '15 minutes to plan, then daily practice', 'The choking fear turns every pill into a crisis and can shrink what a client eats to soft foods. The sheet writes the prediction (it will get stuck, I will not be able to breathe, no one will help), rates it, and sets a graded practice: a sip of water with attention, a crumb, a small candy, a tiny tablet-sized piece of food, then the actual pill, each with the prediction and what the throat actually did. The clinician checks there is no medical reason for the fear before starting. Watch for safety behaviors like excessive chewing or water; record them so they can be reduced too.', '[{"id": "f0", "type": "textarea", "label": "The prediction, word for word, and my confidence out of a hundred:"}, {"id": "f1", "type": "textarea", "label": "My steps, from a sip of water to the actual pill, in my order:"}, {"id": "f2", "type": "textarea", "label": "This week''s step, the prediction for it, and what my throat actually did:"}, {"id": "f3", "type": "textarea", "label": "Safety behaviors I used, honestly: extra chewing, extra water, someone nearby:"}, {"id": "f4", "type": "textarea", "label": "Three days of the same step: how the fear rating changed:"}, {"id": "f5", "type": "textarea", "label": "My confidence in the prediction now, and the next step:"}]'::jsonb, array['phobias', 'predictions', 'exposure']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('moths-at-the-porch-light-willingness-page', 'Moths at the Porch Light Willingness Page', 'act'::resource_kind, 'A willingness page for a client whose fear of moths or other flying insects keeps them from the porch, the garden or the evening walk.', 'Use it to help a client choose an evening outdoors with the flutter present, in service of what the evenings are for.', array['Adults', 'Teens']::text[], '15 minutes, then one evening', 'Fear of moths sounds small and costs whole summers of evenings. The page asks what the porch, the garden or the evening walk is for (the quiet, the partner, the dog), what the fear has taken this year, and what one evening with the moths present would look like if the client were willing: sit on the porch for ten minutes with the light on, let the flutter happen, keep the hands in the lap. The mind''s commentary is invited along and not argued with. Watch for a client who turns the light off to make it bearable; the light is the point.', '[{"id": "f0", "type": "textarea", "label": "What the porch, the garden or the evening walk is for me:"}, {"id": "f1", "type": "textarea", "label": "What the fear has taken this year, in evenings:"}, {"id": "f2", "type": "textarea", "label": "What one willing evening looks like: where I sit, how long, what I do with my hands:"}, {"id": "f3", "type": "textarea", "label": "What my mind will say when the first moth arrives, word for word:"}, {"id": "f4", "type": "textarea", "label": "The evening this week I will try it, and who I will tell:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what the moths did, what I did, and what the evening was like:"}]'::jsonb, array['phobias', 'willingness', 'values']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('cope-ahead-imagery-for-the-dog-walk-past-the-fence-card', 'Cope Ahead Imagery for the Dog Walk Past the Fence Card', 'dbt'::resource_kind, 'A cope ahead card for the daily walk that passes a barking dog behind a fence, rehearsing the skills in imagination before the walk.', 'Use it to give a client with a fear of dogs a rehearsed response to a predictable daily encounter.', array['Adults', 'Teens']::text[], '10 minutes a day for a week', 'Cope ahead works well for a fear with a known time and place: the barking dog behind the fence at the corner. The card describes the situation in detail, names the skills to use (paced breathing from half a block away, a steady walking pace, eyes on the sidewalk ahead, a sentence to say inside), and has the client rehearse the whole walk in imagination each day, including the bark, until it is familiar. Then the real walk is taken with the card in a pocket. Watch for a client who rehearses crossing the street to avoid the fence; the rehearsal is of the walk past it.', '[{"id": "f0", "type": "textarea", "label": "The situation in detail: the corner, the fence, the dog, the time of day:"}, {"id": "f1", "type": "textarea", "label": "The skills I will use, in order, starting half a block away:"}, {"id": "f2", "type": "textarea", "label": "The sentence I will say inside as the barking starts:"}, {"id": "f3", "type": "textarea", "label": "Day by day: the imaginal rehearsal done, and how vivid the bark was:"}, {"id": "f4", "type": "textarea", "label": "The real walk: what the dog did, what I did, and how my body was by the next corner:"}, {"id": "f5", "type": "textarea", "label": "What I will keep rehearsing, and what I no longer need to:"}]'::jsonb, array['phobias', 'cope ahead', 'emotion regulation']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('doctor-kit-pretend-checkup-on-a-teddy-play', 'Doctor Kit Pretend Checkup on a Teddy Play', 'kids'::resource_kind, 'A pretend checkup in which a child uses a toy doctor kit on a stuffed animal, with a parent as the patient''s grown-up, before a real visit.', 'Use it to help a child afraid of doctors and shots rehearse the visit from the powerful side first.', array['Children']::text[], '25 minutes', 'The child is the doctor, the teddy is the patient, and the parent plays the teddy''s grown-up who asks the questions a worried kid might ask. The doctor checks ears, listens to the heart, looks in the mouth, and gives the teddy a pretend shot with a count of three and a sticker. The parent''s part is to narrate the teddy''s feelings (teddy is a bit scared, teddy''s arm pinched for a second and then it stopped), to let the child decide what helps teddy, and to use the same words at the real visit. Watch for a parent who promises the real shot will not hurt; teddy''s pinch is the honest line.', '[{"id": "f0", "type": "textarea", "label": "Doctor, what did you check on teddy first:"}, {"id": "f1", "type": "textarea", "label": "What did teddy feel scared about, and what helped teddy:"}, {"id": "f2", "type": "textarea", "label": "How did the pretend shot go: the count, the pinch, the sticker:"}, {"id": "f3", "type": "textarea", "label": "Grown-up: the words you used for teddy that you will use at the real visit:"}, {"id": "f4", "type": "textarea", "label": "What would you like to bring to your own checkup that helped teddy:"}, {"id": "f5", "type": "textarea", "label": "Draw teddy at the checkup with the thing that helped:"}]'::jsonb, array['phobias', 'children', 'play']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('old-clothes-keep-or-donate-values-sort-sheet', 'Old Clothes Keep or Donate Values Sort Sheet', 'worksheet'::resource_kind, 'A sorting sheet for the clothes kept for a different body, deciding by how each piece serves the client''s life now, not a future self.', 'Use it to help a client clear clothes that function as a daily verdict and keep the ones that serve the life they are living.', array['Adults', 'Teens']::text[], '45 minutes with the closet open', 'Clothes kept for a future body are a judgment hung in the closet, read every morning. The sheet goes piece by piece with three questions that never mention the body: does it feel good to wear today, does it serve something I do in my actual life, does putting it on start a sentence I would not say to a friend. Pieces that fail go to a donate bag the same day; the sheet notes what each one was holding. Watch for a client who keeps everything as motivation; ask what the motivation has actually produced, and whether the morning sentence is the price.', '[{"id": "f0", "type": "textarea", "label": "Pieces I keep for a different version of me, listed:"}, {"id": "f1", "type": "textarea", "label": "For each: does it feel good to wear today, and does it serve something in my actual life:"}, {"id": "f2", "type": "textarea", "label": "The sentence putting it on starts, and whether I would say it to a friend:"}, {"id": "f3", "type": "textarea", "label": "What goes in the donate bag today, and what each piece was holding for me:"}, {"id": "f4", "type": "textarea", "label": "What I keep, and the reason that is about my life now:"}, {"id": "f5", "type": "textarea", "label": "How the closet reads tomorrow morning, in one line:"}]'::jsonb, array['body image', 'values', 'self-talk']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('compliments-about-looks-are-the-only-ones-that-count-sheet', 'Compliments About Looks Are the Only Ones That Count Sheet', 'cbt'::resource_kind, 'A thought check for the belief that appearance compliments are the real currency and every other kind is consolation.', 'Use it to help a client examine why only appearance praise lands and widen what counts as being valued.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients with appearance-focused self-worth hear a compliment about their work or their kindness as what people say when they cannot say you look good. The sheet lists the compliments received this month, sorts them into appearance and everything else, records the belief about which ones count and how much it is believed, and examines it: what the client would want to be remembered for, which compliments they give others and mean, and what the belief costs on a day the mirror is unkind. Watch for a client who has filtered out every non-appearance compliment entirely; walk the month with them.', '[{"id": "f0", "type": "textarea", "label": "Compliments I received this month, as many as I can remember:"}, {"id": "f1", "type": "textarea", "label": "Sorted: the ones about appearance, and everything else:"}, {"id": "f2", "type": "textarea", "label": "The belief about which ones count, word for word, and how much I believe it out of a hundred:"}, {"id": "f3", "type": "textarea", "label": "The compliments I give other people and truly mean, and what they are about:"}, {"id": "f4", "type": "textarea", "label": "What I would want to be remembered for by the people who know me:"}, {"id": "f5", "type": "textarea", "label": "What the belief costs me on a day the mirror is unkind, and my belief in it now:"}]'::jsonb, array['body image', 'thinking traps', 'core beliefs']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('the-mind-s-before-and-after-photo-defusion-page', 'The Mind''s Before and After Photo Defusion Page', 'act'::resource_kind, 'A defusion page for the before-and-after picture the mind keeps producing, in which the after version of the client finally gets to live.', 'Use it to help a client notice the mind''s promised after photo and start living now instead of in the caption.', array['Adults', 'Teens']::text[], '20 minutes', 'The mind runs an advertisement with a before picture (now) and an after picture (later, different, allowed to be happy). The page writes the ad as the mind runs it, including the caption of what the after version is allowed to do (wear that, go there, be seen), notices how long the ad has been running and what has been postponed to the after, and asks what from the caption the client could do this week in the before picture. The ad is not deleted; it is noticed as an ad. Watch for a client who argues with the ad about whether the after will arrive; the move is to do the caption now.', '[{"id": "f0", "type": "textarea", "label": "The ad as my mind runs it: the before picture and the after picture:"}, {"id": "f1", "type": "textarea", "label": "The caption: what the after version is allowed to do, wear, say or go to:"}, {"id": "f2", "type": "textarea", "label": "How long this ad has been running, and what has waited for the after:"}, {"id": "f3", "type": "textarea", "label": "One thing from the caption I could do this week, in the before picture:"}, {"id": "f4", "type": "textarea", "label": "What my mind says about doing it now, noticed as the ad talking:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what it was like to do the after thing in the before body:"}]'::jsonb, array['body image', 'defusion', 'values']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('participate-on-the-dance-floor-without-the-mirror-check-card', 'Participate on the Dance Floor Without the Mirror Check Card', 'dbt'::resource_kind, 'A participate skill card for the wedding or party dance floor, throwing in fully instead of monitoring how the body looks while moving.', 'Use it to help a client who sits out or dances while watching themselves practice full participation for one song.', array['Adults', 'Teens']::text[], 'One song at the next event', 'Many clients dance from the outside, watching their body as if on a screen, which is why they stop after a minute. The participate skill asks for one song danced from the inside: eyes on a friend or the band, attention on the beat and the feet, the self-monitoring noticed and let go each time it comes back. The card sets the song in advance, the person to dance near, and what the client will do with the mirror check when it arrives (turn attention to the bass, to the hands). Watch for a client who picks a slow song to limit movement; the song should be one they would want to dance to.', '[{"id": "f0", "type": "textarea", "label": "The event, and the one song I will dance to from the inside:"}, {"id": "f1", "type": "textarea", "label": "Who I will dance near, and where my eyes will go:"}, {"id": "f2", "type": "textarea", "label": "Where I put my attention: the beat, my feet, the bass, the hands of the person across from me:"}, {"id": "f3", "type": "textarea", "label": "What I do with the mirror check each time it comes: name it, and return attention to:"}, {"id": "f4", "type": "textarea", "label": "Afterward: how much of the song I was inside, and what the mirror check did over the three minutes:"}, {"id": "f5", "type": "textarea", "label": "Would I dance to a second one next time:"}]'::jsonb, array['body image', 'mindfulness', 'participate']::text[], '2026-11-20T15:00:00+00:00'::timestamptz),
  ('does-this-look-okay-honest-kind-answer-script-for-partners', 'Does This Look Okay Honest Kind Answer Script for Partners', 'couples'::resource_kind, 'A script for the daily does-this-look-okay question: what the asking partner really wants, and an answer that is honest and kind.', 'Use it to end a loop where one partner asks for a verdict on their appearance and the other''s answer never lands.', array['Couples']::text[], '20 minutes', 'The question sounds simple and is not: the asker often wants reassurance about their body, the answerer gives an opinion about the outfit, and both leave hurt. The sheet has the asking partner say what they really want when they ask (to be told I am fine, to be told the truth about the shirt, to be looked at), and the answering partner say what the question is like for them. Together they write a reply that is honest about clothes and never about the body, and the asker writes what they will do if they still feel unsure. Watch for a reply that grades the body; the rule is clothes only.', '[{"id": "f0", "type": "textarea", "label": "Asking partner: what I really want when I ask does this look okay:"}, {"id": "f1", "type": "textarea", "label": "Answering partner: what the question is like for me, and what I am afraid of getting wrong:"}, {"id": "f2", "type": "textarea", "label": "Our reply, honest about the clothes and never about the body, written out:"}, {"id": "f3", "type": "textarea", "label": "Asking partner: what I will do if I still feel unsure after the reply:"}, {"id": "f4", "type": "textarea", "label": "Answering partner: what I will not say, however it is asked:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: how many times the question came up, and how the replies landed:"}]'::jsonb, array['body image', 'couples', 'communication']::text[], '2026-11-20T15:00:00+00:00'::timestamptz)
